import numpy as np
import time
import math

try:
    from scipy.signal import fftconvolve
    _HAVE_FFT = True
except Exception:
    _HAVE_FFT = False


def _C_exact(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    if _HAVE_FFT:
        c = fftconvolve(h, h, mode='full')
    else:
        c = np.convolve(h, h)
    return 2.0 * len(h) * np.max(c) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    rng = np.random.default_rng(987654321)

    N = 3000

    # Build initial h by upsampling start (or a default) to N bins.
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones_like(s)
        M = len(s)
        # bin centers of start mapped to [0,1]
        xc = (np.arange(M) + 0.5) / M
        # bin centers of new grid mapped to [0,1]
        xn = (np.arange(N) + 0.5) / N
        h = np.interp(xn, xc, s)
    else:
        h = np.ones(N)

    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(N)
    h = h / h.sum()

    best_h = h.copy()
    best_C = _C_exact(h)

    T0 = 1e-3
    Tmin = 1e-6
    total = max(1e-9, deadline - t0)

    it = 0
    cur_C = best_C
    while True:
        now = time.process_time()
        if now >= deadline:
            break

        frac = (now - t0) / total
        T = T0 * (Tmin / T0) ** frac

        L = int(rng.integers(1, 101))
        if L > N:
            L = N
        i = int(rng.integers(0, N - L + 1))
        factor = math.exp(rng.normal(0.0, 0.01))

        h2 = h.copy()
        h2[i:i + L] *= factor
        h2 = np.maximum(h2, 0.0)
        s2 = h2.sum()
        if s2 <= 0:
            it += 1
            continue
        h2 /= s2

        C2 = _C_fft(h2)

        if C2 < best_C:
            # verify with exact convolution periodically
            if it % 5000 == 0:
                C2e = _C_exact(h2)
                if C2e < best_C:
                    best_h = h2.copy()
                    best_C = C2e
            else:
                best_h = h2.copy()
                best_C = C2

        if C2 <= cur_C:
            h = h2
            cur_C = C2
        else:
            dC = C2 - cur_C
            try:
                prob = math.exp(-dC / (T * max(1e-9, cur_C)))
            except OverflowError:
                prob = 0.0
            if rng.random() < prob:
                h = h2
                cur_C = C2

        it += 1

    # Final exact verification and possible refinement
    best_C = _C_exact(best_h)
    print("iterations:", it, "best_C:", best_C)
    return best_h

