import time
import math

try:
    from scipy.signal import fftconvolve
    _HAVE_FFT = True
except Exception:
    _HAVE_FFT = False


def _C_exact(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    if _HAVE_FFT:
        c = fftconvolve(h, h, mode='full')
    else:
        c = np.convolve(h, h)
    return 2.0 * len(h) * np.max(c) / (s * s)


def _conv_fft(h):
    if _HAVE_FFT:
        return fftconvolve(h, h, mode='full')
    return np.convolve(h, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 3000

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones_like(s)
        M = len(s)
        xc = (np.arange(M) + 0.5) / M
        xn = (np.arange(N) + 0.5) / N
        h = np.interp(xn, xc, s)
    else:
        h = np.ones(N)

    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(N)
    h = h / h.sum()

    best_h = h.copy()
    best_C = _C_exact(h)

    # Active-set subgradient descent
    step = 1e-2
    step_min = 1e-5
    it = 0

    while True:
        now = time.process_time()
        if now >= deadline:
            break

        conv = _conv_fft(h)
        M = conv.max()
        thr = M - 1e-3 * M
        A = (conv >= thr).astype(float)
        nA = A.sum()
        if nA <= 0:
            break

        # gradient: g_i = (2/|A|) * sum_{k in A} h_{k-i}
        # This is correlation of h with A. Use convolution of h with reversed A.
        g_full = _conv_fft(np.concatenate([h, np.zeros_like(h)]))  # not used
        # Proper: correlate h with A over valid range.
        # sum_{k in A} h_{k-i} for i in [0,N-1], k in [0,2N-2]
        # = correlation. Compute via fftconvolve(h, A[::-1]) and slice.
        corr = fftconvolve(h, A[::-1], mode='full') if _HAVE_FFT else np.correlate(h, A, mode='full')
        # corr length N + (2N-1) - 1 = 3N-2; valid i range offset
        # For i in [0,N-1], sum_k h[k-i] A[k] = corr[i + (len(A)-1)] where corr = conv(h, A[::-1])
        # conv(h, A[::-1])[j] = sum_m h[m] A_rev[j-m] = sum_m h[m] A[len(A)-1-(j-m)]
        # want sum_k h[k-i] A[k]: let k = m+i => sum_m h[m] A[m+i]
        # A_rev index: len(A)-1-(j-m) = m+i => j = len(A)-1+i
        g = (2.0 / nA) * corr[len(A) - 1: len(A) - 1 + N]

        h_new = h - step * g
        h_new = np.maximum(h_new, 0.0)
        ssum = h_new.sum()
        if ssum <= 0:
            step *= 0.5
            if step < step_min:
                break
            continue
        h_new /= ssum

        C_new = _C_fft(h_new)
        if C_new < best_C:
            Ce = _C_exact(h_new)
            if Ce < best_C:
                best_C = Ce
                best_h = h_new.copy()

        if C_new < _C_fft(h):
            h = h_new
        else:
            step *= 0.5
            if step < step_min:
                break
            # still accept small move occasionally
            h = h_new

        it += 1

    best_C = _C_exact(best_h)
    print("iterations:", it, "best_C:", best_C)
    return best_h

