import numpy as np
import time
import math

try:
    from scipy.signal import fftconvolve
    _HAVE_FFT = True
except Exception:
    _HAVE_FFT = False

try:
    from scipy.optimize import minimize
    _HAVE_OPT = True
except Exception:
    _HAVE_OPT = False


def _C_exact(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    if _HAVE_FFT:
        c = fftconvolve(h, h, mode='full')
    else:
        c = np.convolve(h, h)
    return 2.0 * len(h) * np.max(c) / (s * s)


def _softmax(z):
    z = z - z.max()
    e = np.exp(z)
    return e / e.sum()


def _softmax_backward(h, g):
    # gradient wrt z given gradient wrt h
    return h * (g - np.sum(g * h))


def _Fp_and_grad(z, p):
    h = _softmax(z)
    N = len(h)
    conv = np.convolve(h, h)  # length 2N-1
    # sum conv^p
    cp = conv ** p
    S = cp.sum()
    if S <= 0:
        return 1e30, np.zeros_like(z)
    F = S ** (1.0 / p)
    # dF/dconv_k = (1/p) S^(1/p-1) * p conv_k^(p-1) = S^(1/p-1) conv_k^(p-1)
    dconv = S ** (1.0 / p - 1.0) * (conv ** (p - 1))
    # conv_k = sum_i h_i h_{k-i}; dconv_k/dh_i = 2 h_{k-i}
    # grad_h_i = sum_k dconv_k * 2 h_{k-i}
    # This is correlation of dconv with h, times 2.
    # grad_h = 2 * correlate(dconv, h) restricted to valid region
    # Use convolution: grad_h_i = 2 * sum_j dconv_{i+j} h_j  (with dconv index i+j)
    # That's 2 * (dconv correlated with h) -> use np.convolve(dconv, h[::-1]) and slice
    corr = np.convolve(dconv, h[::-1])  # length (2N-1)+(N)-1
    # corr index: corr[m] = sum_j dconv[m-j] h_rev[j] = sum_j dconv[m-j] h[N-1-j]
    # we want grad_h_i = 2 sum_j dconv[i+j] h[j]
    # let m = i + N - 1, then corr[m] = sum_j dconv[i+N-1-j] h[N-1-j] = sum_j' dconv[i+j'] h[j'] with j'=N-1-j
    start = N - 1
    grad_h = 2.0 * corr[start:start + N]
    grad_z = _softmax_backward(h, grad_h)
    return F, grad_z


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones_like(s)
    else:
        s = np.ones(3000)
    h = s / s.sum()
    N = len(h)

    best_h = h.copy()
    best_C = _C_exact(h)

    if not _HAVE_OPT:
        print("no scipy.optimize; best_C:", best_C)
        return best_h

    # parameterize via softmax; z = log(h) + const
    z = np.log(np.maximum(h, 1e-12))
    z = z - z.mean()

    ps = [4, 8, 16, 32, 64]
    for p in ps:
        now = time.process_time()
        if now >= deadline:
            break
        # scale maxiter by remaining time
        remaining = deadline - now
        maxiter = 50
        try:
            res = minimize(
                _Fp_and_grad, z, args=(p,), method='L-BFGS-B',
                jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                   'ftol': 1e-14, 'gtol': 1e-12}
            )
            z_new = res.x
        except Exception:
            break
        h_new = _softmax(z_new)
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
            z = z_new
        else:
            # still continue from new z for next p (may help landscape)
            z = z_new
        if time.process_time() >= deadline:
            break

    best_C = _C_exact(best_h)
    print("continuation best_C:", best_C)
    return best_h

