import numpy as np
import time
import math

try:
    from scipy.signal import fftconvolve
    _HAVE_FFT = True
except Exception:
    _HAVE_FFT = False


def _C_exact(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _conv(h):
    if _HAVE_FFT:
        return fftconvolve(h, h, mode='full')
    return np.convolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    return 2.0 * len(h) * np.max(_conv(h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def elapsed():
        return time.process_time() - t0

    # Use a moderate N: fine enough for resolution, cheap enough for many iters.
    N = 2000

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones_like(s)
        M = len(s)
        xc = (np.arange(M) + 0.5) / M
        xn = (np.arange(N) + 0.5) / N
        h = np.interp(xn, xc, s)
    else:
        # Parabola-like bump guess
        x = (np.arange(N) + 0.5) / N
        h = np.maximum(1.0 - ((x - 0.5) * 2.0) ** 2, 0.0) + 0.01

    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(N)
    h = h / h.sum()

    best_h = h.copy()
    best_C = _C_exact(h)

    # Subgradient descent on the max over a soft active set, with
    # momentum-free but adaptive step. The key: use a *smoothed* active set
    # (weights near the max) so the objective is differentiable and we can
    # escape the plateau.
    step = 5e-3
    step_min = 1e-7
    it = 0
    beta = 0.9
    # softmax temperature relative to max
    tau = 1e-2

    while elapsed() < deadline:
        conv = _conv(h)
        M = conv.max()
        if M <= 0:
            break
        # soft weights concentrated near max — a smoothed approximation
        w = np.exp((conv - M) / (tau * M))
        sw = w.sum()
        if sw <= 0:
            break
        w /= sw
        # gradient of sum_k w_k (f*f)_k wrt h_i = 2 * sum_k w_k h_{k-i}
        # = 2 * correlation(h, w) over valid range
        if _HAVE_FFT:
            corr = fftconvolve(h, w[::-1], mode='full')
        else:
            corr = np.correlate(h, w, mode='full')
        # corr[j] = sum_m h[m] w[len(w)-1-(j-m)]; want sum_k h[k-i] w[k] = sum_m h[m] w[m+i]
        # => j = len(w)-1+i
        L = len(w)
        g = 2.0 * corr[L - 1: L - 1 + N]

        # Projected gradient step (nonneg + normalize)
        h_new = h - step * g
        h_new = np.maximum(h_new, 0.0)
        ssum = h_new.sum()
        if ssum <= 0:
            step *= 0.5
            if step < step_min:
                break
            continue
        h_new /= ssum

        C_new = _C(h_new)
        C_old = _C(h)
        if C_new < C_old - 1e-14:
            h = h_new
            if C_new < best_C:
                Ce = _C_exact(h)
                if Ce < best_C:
                    best_C = Ce
                    best_h = h.copy()
            step = min(step * 1.05, 1e-1)
        else:
            # accept equal-ish moves to allow drift, reject worse
            if C_new < C_old + 1e-12:
                h = h_new
            step *= beta
            if step < step_min:
                break
        it += 1

    # Polish: coordinate descent on the fine array with shrinking steps,
    # using exact C to accept. This fine-tunes the bump shape.
    h = best_h.copy()
    s = _C_exact(h)
    lr = 1e-2
    rng = np.random.default_rng(12345)
    idx = np.arange(N)
    while elapsed() < deadline and lr > 1e-8:
        improved = False
        perm = rng.permutation(idx)
        for i in perm:
            if elapsed() >= deadline:
                break
