import numpy as np
import time

try:
    from scipy.signal import fftconvolve
    _HAVE_FFT = True
except Exception:
    _HAVE_FFT = False

try:
    from scipy.optimize import minimize
    _HAVE_OPT = True
except Exception:
    _HAVE_OPT = False


def _C_exact(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _convolve(a, b):
    if _HAVE_FFT:
        return fftconvolve(a, b, mode='full')
    return np.convolve(a, b)


def _softmax(z):
    z = z - z.max()
    e = np.exp(z)
    return e / e.sum()


def _Fp_and_grad(z, p):
    """Smooth max via L^p norm of convolution, gradient wrt logits."""
    h = _softmax(z)
    N = len(h)
    conv = _convolve(h, h)
    # only nonneg matters, but keep all for gradient correctness
    cp = np.abs(conv) ** p
    S = cp.sum()
    if S <= 0 or not np.isfinite(S):
        return 1e30, np.zeros_like(z)
    F = S ** (1.0 / p)
    # d/dconv of S^(1/p) = S^(1/p-1) * p * conv^(p-1) * sign(conv)
    dconv = S ** (1.0 / p - 1.0) * (np.abs(conv) ** (p - 1)) * np.sign(conv)
    # gradient of sum conv*dconv wrt h: 2 * (dconv * h) correlation
    corr = _convolve(dconv, h[::-1])
    start = N - 1
    grad_h = 2.0 * corr[start:start + N]
    # chain through softmax
    grad_z = h * (grad_h - np.sum(grad_h * h))
    return F, grad_z


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    def elapsed():
        return time.process_time() - t0

    N = 3000
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones_like(s)
        M = len(s)
        xc = (np.arange(M) + 0.5) / M
        xn = (np.arange(N) + 0.5) / N
        h = np.interp(xn, xc, s)
    else:
        h = np.ones(N)

    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(N)
    h = h / h.sum()

    best_h = h.copy()
    best_C = _C_exact(h)

    if not _HAVE_OPT:
        print("no scipy.optimize; best_C:", best_C)
        return best_h

    z = np.log(np.maximum(h, 1e-12))
    z = z - z.mean()

    # Progressive p continuation, high -> large
    ps = [4, 8, 16, 32, 64, 128, 256, 512, 1024]
    for p in ps:
        if elapsed() >= budget_seconds * 0.85:
            break
        # allocate remaining time roughly across remaining p's
        maxiter = 200
        try:
            res = minimize(
                _Fp_and_grad, z, args=(p,), method='L-BFGS-B',
                jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                   'ftol': 1e-16, 'gtol': 1e-14}
            )
            z = res.x
        except Exception:
            break
        h_new = _softmax(z)
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new

    # Final: refine at higher resolution using best shape
    if elapsed() < budget_seconds * 0.95:
        # upsample best to larger N and re-run a couple p's
        N2 = 6000
        xc = (np.arange(best_h.size) + 0.5) / best_h.size
        xn = (np.arange(N2) + 0.5) / N2
        h2 = np.interp(xn, xc, best_h)
        h2 = np.maximum(h2, 1e-12)
        h2 = h2 / h2.sum()
        z2 = np.log(h2)
        z2 = z2 - z2.mean()
        for p in [256, 512, 1024]:
            if elapsed() >= budget_seconds * 0.95:
                break
            try:
                res = minimize(
                    _Fp_and_grad, z2, args=(p,), method='L-BFGS-B',
                    jac=True, options={'maxiter': 150, 'maxfun': 450,
                                       'ftol': 1e-16, 'gtol': 1e-14}
                )
                z2 = res.x
            except Exception:
                break
            hh = _softmax(z2)
            c = _C_exact(hh)
            if c < best_C:
                best_h = hh.copy()
                best_C = c

    best_C = _C_exact(best_h)
    print("best C =", best_C, "N =", best_h.size)
    return best_h

