    grad_z = h * (grad_h - np.sum(grad_h * h))
    return F, grad_z


def _subgrad_step(h, lr):
    """One subgradient step on h from the exact-max objective (before softmax)."""
    N = len(h)
    conv = _convolve(h, h)
    m = conv.max()
    if m <= 0:
        return np.zeros_like(h)
    active = np.where(conv >= m * (1.0 - 1e-10))[0]
    # grad_h[k] = 2 * sum_{t in active} h[t-k]  (valid indices)
    # conv index t corresponds to sum_i h[i] h[t-i]; d/dt wrt h[k]: h[t-k]
    grad_h = np.zeros(N)
    for t in active:
        # indices k with 0<=k<N and 0<=t-k<N  => k in [max(0,t-N+1), min(N-1,t)]
        lo = max(0, t - N + 1)
        hi = min(N - 1, t)
        if lo <= hi:
            grad_h[lo:hi + 1] += h[t - lo:t - hi - 1 if t - hi - 1 >= 0 else None:-1] \
                if False else h[(t - np.arange(lo, hi + 1))]
    grad_h *= 2.0
    # grad_z = h * (grad_h - <grad_h, h>)
    return h * (grad_h - np.dot(grad_h, h))


