            C_now = _C_exact(h)
            if C_now < best_C:
                best_h = h.copy()
                best_C = C_now

    # final check
    h_final = _softmax(z)
    C_final = _C_exact(h_final)
    if C_final < best_C:
        best_h = h_final.copy()
        best_C = C_final

    print("subgradient best_C:", best_C)
