    F = S ** (1.0 / p)
    dconv = S ** (1.0 / p - 1.0) * (np.abs(conv) ** (p - 1)) * np.sign(conv)
    corr = _convolve(dconv, h[::-1])
    start = N - 1
    grad_h = 2.0 * corr[start:start + N]
    grad_z = h * (grad_h - np.sum(grad_h * h))
    return F, grad_z


def _C_and_grad(h):
    """Exact max objective C(h) and subgradient wrt h (before softmax)."""
    N = len(h)
    s = h.sum()
    if s <= 0:
        return float('inf'), np.zeros(N)
    conv = _convolve(h, h)
    m = conv.max()
    if m <= 0:
        return float('inf'), np.zeros(N)
    C = 2.0 * N * m / (s * s)
    # gradient wrt h: from max term and normalization
    active = np.where(conv >= m * (1.0 - 1e-9))[0]
    grad_max = np.zeros(N)
    w = 1.0 / len(active)
    for t in active:
        lo = max(0, t - N + 1)
        hi = min(N - 1, t)
        if lo <= hi:
            ks = np.arange(lo, hi + 1)
            grad_max[ks] += w * h[t - ks]
    grad_max *= 2.0
    # C = 2N m / s^2 ; d/dh = 2N/s^2 * grad_max - 4N m / s^3 * 1
    g = 2.0 * N / (s * s) * grad_max - 4.0 * N * m / (s ** 3)
    return C, g


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def elapsed():
        return time.process_time() - t0

    N = 30000
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones_like(s)
        M = len(s)
        xc = (np.arange(M) + 0.5) / M
        xn = (np.arange(N) + 0.5) / N
        h = np.interp(xn, xc, s)
    else:
        h = np.ones(N)

    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(N)
    h = h / h.sum()

    best_h = h.copy()
    best_C = _C_exact(h)
    print("initial best_C:", best_C)

    if not _HAVE_OPT:
        print("no scipy.optimize; best_C:", best_C)
        return best_h

    z = np.log(np.maximum(h, 1e-12))
    z = z - z.mean()

    # Progressive p continuation
    ps = [8, 16, 32, 64, 128, 256, 512, 1024]
    for p in ps:
        if elapsed() >= budget_seconds * 0.70:
            break
        maxiter = 300
        try:
            res = minimize(
                _Fp_and_grad, z, args=(p,), method='L-BFGS-B',
                jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                   'ftol': 1e-16, 'gtol': 1e-14}
            )
            z = res.x
        except Exception:
            break
        h_new = _softmax(z)
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
        print("p=%d best_C=%.10f" % (p, best_C))

    # Exact-max subgradient polish with shrinking lr
    z = np.log(np.maximum(best_h, 1e-12))
    z = z - z.mean()
    n_steps = 5000
    lr_start, lr_end = 2e-3, 1e-6
    for step in range(n_steps):
        if elapsed() >= budget_seconds * 0.97:
            break
        frac = step / max(1, n_steps - 1)
        lr = lr_start * (lr_end / lr_start) ** frac
        h = _softmax(z)
        _, g = _C_and_grad(h)
        gz = h * (g - np.dot(g, h))
        z = z - lr * gz
        if step % 100 == 0:
            C_now = _C_exact(h)
            if C_now < best_C:
                best_h = h.copy()
                best_C = C_now

    h_final = _softmax(z)
    C_final = _C_exact(h_final)
    if C_final < best_C:
        best_h = h_final.copy()
        best_C = C_final

    print("final best_C:", best_C, "N =", best_h.size)
    return best_h

