        M = len(s)
        xc = (np.arange(M) + 0.5) / M
        xn = (np.arange(N) + 0.5) / N
        h = np.interp(xn, xc, s)
    else:
        h = np.ones(N)

    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(N)
    h = h / h.sum()

    best_h = h.copy()
    best_C = _C_exact(h)

    if not _HAVE_OPT:
        print("no scipy.optimize; best_C:", best_C)
