    rng = np.random.RandomState(12345)

    # First: polish start with full continuation to get a solid baseline.
    ps_full = [32, 64, 128, 256, 512, 1024, 2048, 4096]
    hb, cb = _run_pchain(best_h, ps_full, 200, deadline)
    if cb < best_C:
        best_h = hb.copy(); best_C = cb
    print("baseline:", best_C)

    # Repeated random perturbations with larger amplitude, each run through
    # a full continuation (short->long p), keeping the best.
    n_pert = 8
    for k in range(n_pert):
        if time.process_time() >= deadline:
            break
        amp = 0.02 + 0.03 * rng.rand()
        noise = 1.0 + amp * rng.randn(N)
        hp = np.maximum(best_h * noise, 0.0)
        if hp.sum() <= 0:
