        if cb < best_C:
            best_h = hb.copy(); best_C = cb
        print("pert", k, "amp", round(amp, 3), "C:", cb, "best:", best_C)

    # Final high-p polish.
    hb, cb = _run_pchain(best_h, [1024, 2048, 4096, 8192], 250, deadline)
    if cb < best_C:
        best_h = hb.copy(); best_C = cb

    best_C = _C_exact(best_h)
    print("continuation best_C:", best_C)
    return best_h

