            best_C = C_new
        if time.process_time() >= deadline:
            break
    return best_h, best_C


def _simplex_projection(v):
    n = len(v)
    u = np.sort(v)[::-1]
    css = np.cumsum(u)
    rho = np.nonzero(u * np.arange(1, n + 1) > (css - 1.0))[0][-1]
    theta = (css[rho] - 1.0) / (rho + 1.0)
    return np.maximum(v - theta, 0.0)


def _subgradient_polish(h, deadline, max_iter=200):
    """Exact-max subgradient polish on the simplex."""
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h, float('inf')
    h = h / s
    N = len(h)
    best_h = h.copy()
    best_C = _C_exact(h)

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        conv = _convolve(h, h)
        m = conv.max()
        if m <= 0:
            break
        C = 2.0 * N * m / (h.sum() ** 2)
        thr = m - 1e-7 * m
        active = np.nonzero(conv >= thr)[0]
        # subgradient of max(conv) wrt h: sum over active knots of (shifted indicators)
        # conv[k] = sum_i h[i] h[k-i]; d/dh[j] = h[k-j] + h[k-j] (symmetric) -> 2 h[k-j]
        # but conv is symmetric autoconvolution; derivative wrt h[j] = 2*h[k-j] where valid
        g_max = np.zeros(N)
        for k in active:
            # conv[k] = sum_i h[i]*h[k-i], i in [max(0,k-N+1), min(N-1,k)]
            lo = max(0, k - N + 1)
            hi = min(N - 1, k)
            # d/dh[j] for j in [lo,hi]: h[k-j]
            js = np.arange(lo, hi + 1)
            g_max[js] += 2.0 * h[k - js]
        g_max /= len(active)
        # gradient of C = 2N * m / S^2 where S = sum h
        S = h.sum()
        # dC/dh = 2N/S^2 * g_max - 4N*m/S^3
        g = (2.0 * N / (S * S)) * g_max - (4.0 * N * m / (S ** 3))
        # project gradient onto simplex tangent (subtract mean) for stability
        g = g - g.mean()

        t = 1e-4 / np.sqrt(it + 1.0)
        h_new = _simplex_projection(h - t * g)
        if h_new.sum() <= 0:
            break
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
            h = h_new
        else:
            # don't accept; shrink step implicitly via iteration, keep h
            # try a smaller step once
            t2 = t * 0.25
            h_try = _simplex_projection(h - t2 * g)
            if h_try.sum() > 0:
                C_try = _C_exact(h_try)
                if C_try < best_C:
                    best_h = h_try.copy()
                    best_C = C_try
                    h = h_try
    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.9

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones_like(s)
    else:
        s = np.ones(3000)

    ps_full = [8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192]

    # Stage 1: N=6000
    h = _resample(s, 6000)
    best_h, best_C = _run_continuation(h, ps_full, deadline, maxiter=300)
    print("stage1 N=6000 best_C:", best_C)

    # Stage 2: upsample to N=12000, refine p>=1024
    if time.process_time() < deadline:
        h2 = _resample(best_h, 12000)
        ps_fine = [1024, 2048, 4096, 8192]
        h2b, C2 = _run_continuation(h2, ps_fine, deadline, maxiter=300)
        if C2 < best_C:
            best_h, best_C = h2b, C2
        print("stage2 N=12000 best_C:", best_C)

    best_C = _C_exact(best_h)
    print("continuation best_C:", best_C)

    # Stage 3: exact-max subgradient polish at N=12000
    if time.process_time() < deadline:
        hp = _resample(best_h, 12000)
        hp = np.maximum(hp, 0.0)
        if hp.sum() > 0:
