    if m <= 0 or not np.isfinite(m):
        return 1e30, np.zeros_like(h)
    sc = conv / m
    sp = sc ** p
    S = sp.sum()
    if S <= 0 or not np.isfinite(S):
        return 1e30, np.zeros_like(h)
    F = m * S ** (1.0 / p)
    dconv = S ** (1.0 / p - 1.0) * (sc ** (p - 1))
    corr = _convolve(dconv, hn[::-1])
    st = N - 1
    grad_hn = 2.0 * corr[st:st + N]
    # chain through normalisation: dhn/dh
    grad_h = (grad_hn - np.sum(grad_hn * hn)) / s
    # through abs
    grad_h = grad_h * np.sign(h + 1e-300)
    return F, grad_h


def _resample(h, N):
    M = len(h)
    if M == N:
        return h.copy()
    xc = (np.arange(M) + 0.5) / M
    xn = (np.arange(N) + 0.5) / N
    return np.interp(xn, xc, h)


def _run(h, ps, deadline, maxiter=200):
    h = np.maximum(np.abs(h), 1e-12)
    h = h / h.sum()
    best_h = h.copy()
    best_C = _C_exact(h)
    if not _HAVE_OPT:
        return best_h, best_C
    x = h.copy()
    for p in ps:
        if time.process_time() >= deadline:
            break
        try:
            res = minimize(
                _Fp_and_grad, x, args=(p,), method='L-BFGS-B',
                jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                   'ftol': 1e-15, 'gtol': 1e-13}
            )
            x = res.x
        except Exception:
            break
        h_new = np.maximum(np.abs(x), 0.0)
        if h_new.sum() <= 0:
            continue
        h_new = h_new / h_new.sum()
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
        x = h_new.copy()
        if time.process_time() >= deadline:
            break
    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones(3000)
    else:
        s = np.ones(3000)

    M = len(s)
    best_h = s / s.sum()
    best_C = _C_exact(best_h)
    print("start C:", best_C, "N:", M)

    # Refine at higher resolution where the true optimum is better resolved.
    for N in (8000, 16000, 30000):
        if time.process_time() >= deadline:
            break
        h2 = _resample(best_h, N)
        ps = [512, 1024, 2048, 4096, 8192, 16384]
        hb, Cb = _run(h2, ps, deadline, maxiter=250)
        if Cb < best_C:
            best_h, best_C = hb, Cb
        print("stage N=%d best_C: %.10f" % (N, best_C))

    best_C = _C_exact(best_h)
    print("final best_C:", best_C, "N:", len(best_h))
    return best_h

