def _active_set_lp(h0, K=256):
    """Solve linearized active-set LP. Returns h_lp (normalized) or None."""
    N = len(h0)
    conv00 = _convolve(h0, h0)
    # select K largest knots
    idx = np.argpartition(conv00, -K)[-K:]
    # Build constraint matrix: for each selected k, 2*conv(h0,h)[k] - conv00[k] <= t
    # conv(h0,h)[k] = sum_j h0[j]*h[k-j]  (valid indices)
    # We need matrix A (K x N) where A[i,j] = 2*h0[j] if 0<=k_i-j<N else 0
    A = np.zeros((K, N))
    for i, k in enumerate(idx):
        jlo = max(0, k - (N - 1))
        jhi = min(N - 1, k)
        if jhi >= jlo:
            A[i, jlo:jhi + 1] = 2.0 * h0[jlo:jhi + 1][::-1] if False else 0.0
            # careful: conv(h0,h)[k] = sum_j h0[j] * h[k-j]
            # so coefficient of h[j] is h0[k-j]... wait
            # conv(h0,h)[k] = sum_j h0[j]*h[k-j]
            # coefficient of h[m] is h0[k-m]
            for m in range(jlo, jhi + 1):
                A[i, m] = 2.0 * h0[k - m]
    b = conv00[idx]
    # variables: h (N) and t (1). minimize t
    c = np.zeros(N + 1)
    c[N] = 1.0
    # A_ub: A @ h - t <= b
    A_ub = np.hstack([A, -np.ones((K, 1))])
    b_ub = b
    # equality: sum(h) = 1
    A_eq = np.zeros((1, N + 1))
    A_eq[0, :N] = 1.0
    b_eq = np.array([1.0])
    bounds = [(0, None)] * N + [(None, None)]
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                      bounds=bounds, method='highs')
        if not res.success:
            return None
        h_lp = res.x[:N]
        h_lp = np.maximum(h_lp, 0.0)
        s = h_lp.sum()
        if s <= 0:
            return None
        return h_lp / s
    except Exception:
        return None


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.9

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones_like(s)
    else:
        s = np.ones(3000)

    best_h = s.copy()
    best_C = _C_exact(best_h)
    N_orig = len(best_h)

    # Active-set LP phase at N=2400
    if _HAVE_OPT and time.process_time() < deadline:
        h_small = _resample(best_h, 2400)
        h_small = np.maximum(h_small, 0.0)
        if h_small.sum() > 0:
            h_small = h_small / h_small.sum()
        C_small = _C_exact(h_small)
        h_cur = h_small.copy()
        for it in range(10):
            if time.process_time() >= deadline:
                break
            h_lp = _active_set_lp(h_cur, K=256)
            if h_lp is None:
                break
            # backtracking line search
            a = 1.0
            improved = False
            for _ in range(20):
                h_try = (1.0 - a) * h_cur + a * h_lp
                h_try = np.maximum(h_try, 0.0)
                st = h_try.sum()
                if st <= 0:
                    a *= 0.5
                    continue
                h_try = h_try / st
                C_try = _C_exact(h_try)
                if C_try < C_small - 1e-14:
                    h_cur = h_try
                    C_small = C_try
                    improved = True
                    break
                a *= 0.5
            if not improved:
                break
        if C_small < best_C:
            # resample back
            h_back = _resample(h_cur, N_orig)
            h_back = np.maximum(h_back, 0.0)
            if h_back.sum() > 0:
                h_back = h_back / h_back.sum()
                C_back = _C_exact(h_back)
                if C_back < best_C:
                    best_h = h_back
                    best_C = C_back
        print("active-set N=2400 best_C:", C_small, "global:", best_C)

    # Short p-continuation at original N
    if _HAVE_OPT and time.process_time() < deadline:
        hb, Cb = _run_continuation(best_h, [4096, 16384], deadline, maxiter=100)
        if Cb < best_C:
            best_h, best_C = hb, Cb
        print("p-continuation best_C:", best_C)

    best_C = _C_exact(best_h)
    print("final best_C:", best_C)
    return best_h

