    best_h = h.copy()
    best_C = _C_exact(h)
    z = np.log(np.maximum(h, 1e-14))
    z = z - z.mean()
    for p in ps:
        if time.process_time() >= deadline:
            break
        try:
            res = minimize(
                _Fp_and_grad, z, args=(p,), method='L-BFGS-B',
                jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                   'ftol': 1e-16, 'gtol': 1e-14}
            )
            z = res.x
        except Exception:
            break
        zz = z - z.max()
        e = np.exp(zz)
        h_new = e / e.sum()
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
    return best_h, best_C


