import numpy as np
import time

try:
    from scipy.signal import fftconvolve
    _HAVE_FFT = True
except Exception:
    _HAVE_FFT = False

try:
    from scipy.optimize import minimize
    _HAVE_OPT = True
except Exception:
    _HAVE_OPT = False


def _C_exact(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _convolve(a, b):
    if _HAVE_FFT:
        return fftconvolve(a, b, mode='full')
    return np.convolve(a, b)


def _Fp_and_grad(h, p):
    h = np.abs(h)
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return 1e30, np.zeros_like(h)
    hn = h / s
    N = len(hn)
    conv = _convolve(hn, hn)
    m = conv.max()
    if m <= 0 or not np.isfinite(m):
        return 1e30, np.zeros_like(h)
    sc = conv / m
    sp = sc ** p
    S = sp.sum()
    if S <= 0 or not np.isfinite(S):
        return 1e30, np.zeros_like(h)
    F = m * S ** (1.0 / p)
    dconv = S ** (1.0 / p - 1.0) * (sc ** (p - 1))
    corr = _convolve(dconv, hn[::-1])
    st = N - 1
    grad_hn = 2.0 * corr[st:st + N]
    grad_h = (grad_hn - np.sum(grad_hn * hn)) / s
    grad_h = grad_h * np.sign(h + 1e-300)
    return F, grad_h


def _resample(h, N):
    M = len(h)
    if M == N:
        return h.copy()
    xc = (np.arange(M) + 0.5) / M
    xn = (np.arange(N) + 0.5) / N
    return np.interp(xn, xc, h)


def _run(h, ps, deadline, maxiter=200):
    h = np.maximum(np.abs(h), 1e-12)
    h = h / h.sum()
    best_h = h.copy()
    best_C = _C_exact(h)
    if not _HAVE_OPT:
        return best_h, best_C
    x = h.copy()
    for p in ps:
        if time.process_time() >= deadline:
            break
        try:
            res = minimize(
                _Fp_and_grad, x, args=(p,), method='L-BFGS-B',
                jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                   'ftol': 1e-15, 'gtol': 1e-13}
            )
            x = res.x
        except Exception:
            break
        h_new = np.maximum(np.abs(x), 0.0)
        if h_new.sum() <= 0:
            continue
        h_new = h_new / h_new.sum()
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
        x = h_new.copy()
        if time.process_time() >= deadline:
            break
    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones(3000)
    else:
        s = np.ones(3000)

    M = len(s)
    best_h = s / s.sum()
    best_C = _C_exact(best_h)
    print("start C:", best_C, "N:", M)

    # Use the existing start directly at its own resolution, then refine upward.
    # Skip the coarse stages if start is already large, to save time.
    if M >= 16000:
        stages = [M, 30000] if M != 30000 else [30000]
    elif M >= 8000:
        stages = [M, 16000, 30000]
    else:
        stages = [8000, 16000, 30000]

    for N in stages:
        if time.process_time() >= deadline:
            break
        h2 = _resample(best_h, N)
        # Warm-start with a couple of mid-p steps then refine.
        ps = [1024, 2048, 4096, 8192, 16384]
        hb, Cb = _run(h2, ps, deadline, maxiter=250)
        if Cb < best_C:
            best_h, best_C = hb, Cb
        print("stage N=%d best_C: %.10f" % (N, best_C))

    # Final polish at full resolution with extra p values.
    if time.process_time() < deadline:
        hb, Cb = _run(best_h, [4096, 8192, 16384, 32768], deadline, maxiter=300)
        if Cb < best_C:
            best_h, best_C = hb, Cb
        print("final polish best_C: %.10f" % best_C)

    best_C = _C_exact(best_h)
    print("final best_C:", best_C, "N:", len(best_h))
    return best_h

