import numpy as np
import time

try:
    from scipy.signal import fftconvolve
    _HAVE_FFT = True
except Exception:
    _HAVE_FFT = False

try:
    from scipy.optimize import minimize, least_squares
    _HAVE_OPT = True
except Exception:
    _HAVE_OPT = False


def _C_exact(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _convolve(a, b):
    if _HAVE_FFT:
        return fftconvolve(a, b, mode='full')
    return np.convolve(a, b)


def _softmax(z):
    z = z - z.max()
    e = np.exp(z)
    return e / e.sum()


def _Fp_and_grad(z, p):
    h = _softmax(z)
    N = len(h)
    conv = _convolve(h, h)
    m = conv.max()
    if m <= 0 or not np.isfinite(m):
        return 1e30, np.zeros_like(z)
    s = conv / m
    sp = s ** p
    S = sp.sum()
    if S <= 0 or not np.isfinite(S):
        return 1e30, np.zeros_like(z)
    F = m * S ** (1.0 / p)
    dconv = S ** (1.0 / p - 1.0) * (s ** (p - 1))
    corr = _convolve(dconv, h[::-1])
    start = N - 1
    grad_h = 2.0 * corr[start:start + N]
    grad_z = h * (grad_h - np.sum(grad_h * h))
    return F, grad_z


def _resample(h, N):
    M = len(h)
    if M == N:
        return h.copy()
    xc = (np.arange(M) + 0.5) / M
    xn = (np.arange(N) + 0.5) / N
    return np.interp(xn, xc, h)


def _run_continuation(h, ps, deadline, maxiter=300):
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones_like(h)
    h = h / h.sum()
    best_h = h.copy()
    best_C = _C_exact(h)
    if not _HAVE_OPT:
        return best_h, best_C
    z = np.log(np.maximum(h, 1e-12))
    z = z - z.mean()
    for p in ps:
        if time.process_time() >= deadline:
            break
        try:
            res = minimize(
                _Fp_and_grad, z, args=(p,), method='L-BFGS-B',
                jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                   'ftol': 1e-15, 'gtol': 1e-13}
            )
            z = res.x
        except Exception:
            break
        h_new = _softmax(z)
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
        if time.process_time() >= deadline:
            break
    return best_h, best_C


def _kkt_refine(h, deadline, tol=1e-5, max_outer=4):
    """Solve the KKT system on the active set of near-max knots."""
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h, _C_exact(h)
    h = h / s
    N = len(h)
    best_h = h.copy()
    best_C = _C_exact(h)
    if not _HAVE_OPT:
        return best_h, best_C

    for outer in range(max_outer):
        if time.process_time() >= deadline:
            break
        conv = _convolve(h, h)
        M = conv.max()
        A = np.where(conv >= M * (1.0 - tol))[0]
        nA = len(A)
        if nA == 0:
            break

        # Variables: x = [h (N), lam (nA), M (1)]
        nvar = N + nA + 1
        iM = N + nA

        # Precompute correlation matrices: grad conv_k = 2 * correlate(e_k, h)
        # correlate(e_k, h)[j] for j in 0..N-1 = h[j - (k-(N-1))] if in range
        # We'll compute full correlation via fft for each k in A (nA could be large).
        # Instead, grad of sum lam_k conv_k = 2 * correlate(sum lam_k e_k, h)
        # = 2 * correlate(lam_padded, h). Build lam_padded over full conv index range.

        def residuals(x):
            hh = x[:N]
            lam = x[N:N + nA]
            MM = x[iM]
            # conv_k(hh) - M for k in A
            cv = _convolve(hh, hh)
            r1 = cv[A] - MM
            # sum(h) - 1
            r2 = np.array([hh.sum() - 1.0])
            # sum(lam) - 1
            r3 = np.array([lam.sum() - 1.0])
            # gradient of L = sum lam_k conv_k wrt h, projected orthogonal to ones
            # lam_padded: conv index k corresponds to full conv index k (0..2N-2)
            lam_full = np.zeros(2 * N - 1)
            lam_full[A] = lam
            # grad conv_k = 2 * correlate(e_k, h) where correlate(a,b)[j] = sum a[i] b[i+j-(len(b)-1)]
            # For a = e_k (length 2N-1), b = h (length N):
            # correlate(e_k, h)[j] = h[j - (k - (N-1))] if 0<=...<N
            # sum_k lam_k grad conv_k = 2 * correlate(lam_full, h)
            g = 2.0 * _convolve(lam_full, h[::-1])
            # correlate(lam_full, h) has length (2N-1)+N-1 = 3N-2; take middle N
            start = N - 1
            grad_h = g[start:start + N]
            # project orthogonal to ones: subtract mean
            grad_h = grad_h - grad_h.mean()
            return np.concatenate([r1, r2, r3, grad_h])

        # Initial guess
        x0 = np.concatenate([h, np.full(nA, 1.0 / nA), [M]])

        try:
            res = least_squares(residuals, x0, method='lm',
                                max_nfev=200, ftol=1e-14, xtol=1e-14, gtol=1e-14)
            x = res.x
        except Exception:
            break

        h_new = np.maximum(x[:N], 0.0)
        if h_new.sum() <= 0:
            break
        h_new = h_new / h_new.sum()
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
        h = h_new
        if time.process_time() >= deadline:
            break

    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.9

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones_like(s)
    else:
        s = np.ones(3000)

    best_h = s.copy()
    best_C = _C_exact(best_h)

    # Stage 1: refine start via p-norm continuation at its own resolution
    if time.process_time() < deadline:
        N0 = len(best_h)
        ps0 = [4096, 8192, 16384]
        h0b, C0 = _run_continuation(best_h, ps0, deadline, maxiter=100)
        if C0 < best_C:
            best_h, best_C = h0b, C0
        print("stage1 N=%d best_C:" % N0, best_C)

    # Stage 2: KKT refine on active set
    if time.process_time() < deadline:
        hk, Ck = _kkt_refine(best_h, deadline, tol=1e-5, max_outer=4)
        if Ck < best_C:
            best_h, best_C = hk, Ck
        print("stage2 KKT best_C:", best_C)

    # Stage 3: one more continuation polish if time remains
    if time.process_time() < deadline:
        hp, Cp = _run_continuation(best_h, [8192, 16384], deadline, maxiter=60)
        if Cp < best_C:
            best_h, best_C = hp, Cp
        print("stage3 polish best_C:", best_C)

    best_C = _C_exact(best_h)
    print("final best_C:", best_C)
    return best_h

