        return 1e30, np.zeros_like(z)
    k = int(min(max(k, 1), len(conv)))
    idx = np.argpartition(conv, -k)[-k:]
    F = float(conv[idx].sum())
    dconv = np.zeros_like(conv)
    dconv[idx] = 1.0
    corr = _convolve(dconv, h[::-1])
    start = N - 1
    grad_h = 2.0 * corr[start:start + N]
    # symmetry: h = (h + h[::-1])/2, chain rule
    grad_h = 0.5 * (grad_h + grad_h[::-1])
    grad_z = h * (grad_h - np.sum(grad_h * h))
    return F, grad_z


def _Fp_and_grad(z, p):
    h = _softmax(z)
    h = 0.5 * (h + h[::-1])
    N = len(h)
    conv = _convolve(h, h)
    m = conv.max()
    if m <= 0 or not np.isfinite(m):
        return 1e30, np.zeros_like(z)
    s = conv / m
    sp = s ** p
    S = sp.sum()
    if S <= 0 or not np.isfinite(S):
        return 1e30, np.zeros_like(z)
    F = m * S ** (1.0 / p)
    dconv = S ** (1.0 / p - 1.0) * (s ** (p - 1))
    corr = _convolve(dconv, h[::-1])
    start = N - 1
    grad_h = 2.0 * corr[start:start + N]
    grad_h = 0.5 * (grad_h + grad_h[::-1])
    grad_z = h * (grad_h - np.sum(grad_h * h))
    return F, grad_z


def _resample(h, N):
    M = len(h)
    if M == N:
        return h.copy()
    xc = (np.arange(M) + 0.5) / M
    xn = (np.arange(N) + 0.5) / N
    return np.interp(xn, xc, h)


def _run_topk(h, ks, deadline, maxiter=200):
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones_like(h)
    h = h / h.sum()
    h = 0.5 * (h + h[::-1])
    best_h = h.copy()
    best_C = _C_exact(h)
    if not _HAVE_OPT:
        return best_h, best_C
    z = np.log(np.maximum(h, 1e-12))
    z = z - z.mean()
    for k in ks:
        if time.process_time() >= deadline:
            break
        try:
            res = minimize(
                _topk_and_grad, z, args=(k,), method='L-BFGS-B',
                jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                   'ftol': 1e-15, 'gtol': 1e-13}
            )
            z = res.x
        except Exception:
            break
        h_new = _softmax(z)
        h_new = 0.5 * (h_new + h_new[::-1])
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
        if time.process_time() >= deadline:
            break
    return best_h, best_C


def _run_continuation(h, ps, deadline, maxiter=250):
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones_like(h)
    h = h / h.sum()
    h = 0.5 * (h + h[::-1])
    best_h = h.copy()
