import numpy as np
import time
import math
from scipy.signal import fftconvolve


def _C_exact(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    c = fftconvolve(h, h, mode='full')
    return 2.0 * len(h) * np.max(c) / (s * s)


def _resample(h, N):
    M = len(h)
    if M == N:
        return h.copy()
    xc = (np.arange(M) + 0.5) / M
    xn = (np.arange(N) + 0.5) / N
    return np.interp(xn, xc, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    rng = np.random.default_rng(12345)

    N = 900
    if start is not None:
        h0 = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if h0.size == 0 or h0.sum() <= 0:
            h0 = None
    else:
        h0 = None

    if h0 is not None:
        h = _resample(h0, N)
    else:
        h = np.empty(N)
        h[:N // 2] = 1.0
        h[N // 2:] = 2.0
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        h = np.ones(N)
        s = N
    h = h / s * N

    best_h = h.copy()
    best_C = _C_exact(h)
    cur_C = best_C

    T0 = 1e-4
    Tmin = 1e-9

    it = 0
    while True:
        now = time.process_time()
        if now >= deadline:
            break

        frac = (now - t0) / max(1e-9, (deadline - t0))
        T = T0 * (Tmin / T0) ** frac

        r = rng.random()
        if r < 0.25:
            L = int(rng.integers(1, 16))
            if L > N:
                L = N
            i = int(rng.integers(0, N - L + 1))
            factor = 1.0 + rng.normal(0.0, 0.01)
            h2 = h.copy()
            h2[i:i + L] *= factor
        elif r < 0.7:
            i = int(rng.integers(0, N))
            j = int(rng.integers(0, N - 1))
            if j >= i:
                j += 1
            amount = rng.uniform(0.0, h[i]) * 0.2
            h2 = h.copy()
            h2[i] -= amount
            h2[j] += amount
        else:
            i = int(rng.integers(0, N))
            j = int(rng.integers(0, N))
            h2 = h.copy()
            m = 0.5 * (h2[i] + h2[j])
            alpha = rng.uniform(0.0, 0.5)
            h2[i] = h2[i] * (1 - alpha) + m * alpha
            h2[j] = h2[j] * (1 - alpha) + m * alpha

        if h2.sum() <= 0:
            continue

        h2 *= (N / h2.sum())

        C2 = _C_fft(h2)

        if C2 < best_C - 1e-7:
            C2 = _C_exact(h2)
            if C2 < best_C:
                best_h = h2.copy()
                best_C = C2

        if C2 <= cur_C:
            h = h2
            cur_C = C2
        else:
            dC = C2 - cur_C
            try:
                prob = math.exp(-dC / (T * max(1e-9, best_C)))
            except OverflowError:
                prob = 0.0
            if rng.random() < prob:
                h = h2
                cur_C = C2

        it += 1

    # Final polish: coordinate-wise greedy smoothing on best_h
    h = best_h.copy()
    cur_C = best_C
    step = 0.05
    while time.process_time() < deadline:
        improved = False
        order = rng.permutation(N)
        for idx in order:
            if time.process_time() >= deadline:
                break
            for delta in (step, -step):
                h2 = h.copy()
                h2[idx] = max(0.0, h2[idx] + delta)
                if h2.sum() <= 0:
                    continue
                h2 *= (N / h2.sum())
                C2 = _C_fft(h2)
                if C2 < cur_C - 1e-9:
                    C2e = _C_exact(h2)
                    if C2e < cur_C - 1e-12:
                        h = h2
                        cur_C = C2e
                        improved = True
                        break
        if not improved:
            step *= 0.5
            if step < 1e-6:
                break
        if cur_C < best_C:
            best_C = cur_C
            best_h = h.copy()

    print("iterations:", it, "best_C:", best_C)
    return best_h

