    else:
        h = np.ones(300)
        h /= h.sum()

    base_C = _C_exact(h)
    print("start N=%d C=%.9f" % (len(h), base_C))

    # The current best solution is at low N (300).  The minimax objective is
    # accurately captured there; high-N continuation is expensive and tends to
    # over-fit convolution knots.  Focus budget on strong continuation at the
    # native N, then a modest upsampling at the very end.
    ps = [32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536]
    best_h, best_C = _run_continuation(h, ps, 500, deadline)
    print("stage1 N=%d C=%.9f" % (len(best_h), best_C))

    # Try a fine upsampling to check if the true optimum wants more resolution.
    if time.process_time() < deadline and len(best_h) < 30000:
        for N2 in (600, 1200, 2400):
            if time.process_time() >= deadline:
                break
            h2 = _resample(best_h, N2)
