import numpy as np
import time
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _C_exact(h):
    s = h.sum()
    if s <= 0:
        return float('inf')
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _softmax(z):
    z = z - z.max()
    e = np.exp(z)
    return e / e.sum()


def _resample(h, N):
    M = len(h)
    if M == N:
        return h.copy()
    xc = (np.arange(M) + 0.5) / M
    xn = (np.arange(N) + 0.5) / N
    return np.interp(xn, xc, h)


def _Fp_and_grad_lse(z, p):
    h = _softmax(z)
    N = len(h)
    conv = fftconvolve(h, h, mode='full')
    m = conv.max()
    if m <= 0 or not np.isfinite(m):
        return 1e30, np.zeros_like(z)
    s = conv / m
    t = p * (s - 1.0)
    tmax = t.max()
    e = np.exp(t - tmax)
    Se = e.sum()
    if Se <= 0 or not np.isfinite(Se):
        return 1e30, np.zeros_like(z)
    LSE = tmax + np.log(Se)
    F = m * (1.0 + LSE / p)
    dconv = (e / Se) / m
    corr = fftconvolve(dconv, h[::-1], mode='full')
    start = N - 1
    grad_h = 2.0 * corr[start:start + N]
    grad_z = h * (grad_h - np.sum(grad_h * h))
    return F, grad_z


def _run_continuation(h, ps, deadline, maxiter=250):
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones_like(h)
    h = h / h.sum()
    best_h = h.copy()
    best_C = _C_exact(h)
    z = np.log(np.maximum(h, 1e-12))
    z = z - z.mean()
    for p in ps:
        if time.process_time() >= deadline:
            break
        try:
            res = minimize(
                _Fp_and_grad_lse, z, args=(p,), method='L-BFGS-B',
                jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                   'ftol': 1e-15, 'gtol': 1e-13}
            )
            z = res.x
        except Exception:
            break
        h_new = _softmax(z)
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
        if time.process_time() >= deadline:
            break
    return best_h, best_C


def _polish_minimax(h, deadline, iters=60):
    """Directly minimise the true C via subgradient on the argmax region.

    Uses the fact that at the optimum the max region is broad; we shift mass
    via a smoothed max (high-p LSE) but do a final direct C-based local check
    by perturbing the plateau region with a small smoothing kernel.
    """
    N = len(h)
    best_h = h.copy()
    best_C = _C_exact(h)
    # Try a few small triangular smoothing passes on the plateau - the
    # minimax optimum tends to be a flat-topped trapezoid; smoothing the
    # shoulder can shave the peak of the autoconvolution.
    for width in (1, 2, 3, 5):
        if time.process_time() >= deadline:
            break
        k = np.ones(2 * width + 1)
        k /= k.sum()
        hh = np.convolve(h, k, mode='same')
        if hh.sum() <= 0:
            continue
        hh = np.maximum(hh, 0.0)
        C = _C_exact(hh)
        if C < best_C:
            best_h = hh.copy()
            best_C = C
    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones(3000)
    else:
        s = np.ones(3000)

    best_h = s / s.sum()
    best_C = _C_exact(best_h)
    print("start N=%d C=%.9f" % (len(best_h), best_C))

    # Stage 1: refine at native N with high p continuation.
    if time.process_time() < deadline:
        ps_native = [2048, 4096, 8192, 16384, 32768]
        h1, C1 = _run_continuation(best_h, ps_native, deadline, maxiter=200)
        if C1 < best_C:
            best_h, best_C = h1, C1
        print("stage1 N=%d C=%.9f" % (len(best_h), best_C))

    # Stage 2: polish the plateau shape against true C.
    if time.process_time() < deadline:
        h2, C2 = _polish_minimax(best_h, deadline)
        if C2 < best_C:
            best_h, best_C = h2, C2
        print("stage2 N=%d C=%.9f" % (len(best_h), best_C))

    # Stage 3: push to 30000 with very high p (reduces surrogate bias).
    if time.process_time() < deadline and len(best_h) < 30000:
        h3 = _resample(best_h, 30000)
        ps_fine = [4096, 8192, 16384, 32768, 65536]
        h3b, C3 = _run_continuation(h3, ps_fine, deadline, maxiter=150)
        if C3 < best_C:
            best_h, best_C = h3b, C3
        print("stage3 N=%d C=%.9f" % (len(best_h), best_C))

    # Stage 4: final polish at 30000 against true C.
    if time.process_time() < deadline:
        h4b, C4 = _polish_minimax(best_h, deadline)
        if C4 < best_C:
            best_h, best_C = h4b, C4
        print("stage4 N=%d C=%.9f" % (len(best_h), best_C))

    # Stage 5: very high p LSE to shave the peak bias.
    if time.process_time() < deadline:
        h5b, C5 = _run_continuation(best_h, [1e5, 2e5, 5e5], deadline, maxiter=120)
        if C5 < best_C:
