    xc = (np.arange(M) + 0.5) / M
    xn = (np.arange(N) + 0.5) / N
    return np.interp(xn, xc, h)


def _block_average(h, N):
    M = len(h)
    if M == N:
        return h.copy()
    if M % N == 0:
        k = M // N
        return h.reshape(N, k).mean(axis=1)
    # fallback: resample
    return _resample(h, N)


