    if m <= 0 or not np.isfinite(m):
        return 1e30, np.zeros_like(z)
    s = conv / m
    bs = beta * s
    bs_max = bs.max()
    e = np.exp(bs - bs_max)
    S = e.sum()
    lse = bs_max + np.log(S)
    F = m * lse / beta
    w = e / S
    j = int(np.argmax(conv))
    e_j = np.zeros_like(conv)
    e_j[j] = 1.0
    mean_s = float(np.sum(w * s))
    corr_coef = lse / beta - mean_s
    dF_dconv = w + corr_coef * e_j
    corr = fftconvolve(dF_dconv, h[::-1], mode='full')
    start = N - 1
    grad_h = 2.0 * corr[start:start + N]
    grad_z = h * (grad_h - np.sum(grad_h * h))
    return F, grad_z


def _Fmax_and_grad(z):
    h = _softmax(z)
    N = len(h)
    conv = fftconvolve(h, h, mode='full')
    m = conv.max()
    if m <= 0 or not np.isfinite(m):
        return 1e30, np.zeros_like(z)
    active = conv >= m * (1.0 - 1e-6)
    na = active.sum()
    if na == 0:
        na = 1
        active[int(np.argmax(conv))] = True
    dF_dconv = active.astype(float) / na
    corr = fftconvolve(dF_dconv, h[::-1], mode='full')
    start = N - 1
    grad_h = 2.0 * corr[start:start + N]
    grad_z = h * (grad_h - np.sum(grad_h * h))
    return m, grad_z


def _run_continuation(h, betas, deadline, maxiter=200):
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones_like(h)
    h = h / h.sum()
    best_h = h.copy()
    best_C = _C_exact(h)
    z = np.log(np.maximum(h, 1e-12))
    z = z - z.mean()
    for beta in betas:
        if time.process_time() >= deadline:
            break
        try:
            res = minimize(
                _Fbeta_and_grad, z, args=(beta,), method='L-BFGS-B',
                jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                   'ftol': 1e-15, 'gtol': 1e-13}
            )
            z = res.x
        except Exception:
            break
        h_new = _softmax(z)
        C_new = _C_exact(h_new)
        if C_new < best_C:
            best_h = h_new.copy()
            best_C = C_new
        if time.process_time() >= deadline:
            break
    return best_h, best_C


def _active_polish(h, deadline, maxiter=400, tol=1e-6):
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones_like(h)
    h = h / h.sum()
    best_h = h.copy()
    best_C = _C_exact(h)
    z = np.log(np.maximum(h, 1e-12))
    z = z - z.mean()
    if time.process_time() >= deadline:
        return best_h, best_C
    try:
        res = minimize(
            lambda zz: _Fmax_and_grad_tol(zz, tol), z, method='L-BFGS-B', jac=True,
            options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                     'ftol': 1e-16, 'gtol': 1e-14}
        )
        z = res.x
    except Exception:
        return best_h, best_C
    h_new = _softmax(z)
    C_new = _C_exact(h_new)
    if C_new < best_C:
        best_h = h_new.copy()
        best_C = C_new
    return best_h, best_C


def _Fmax_and_grad_tol(z, tol):
    h = _softmax(z)
    N = len(h)
    conv = fftconvolve(h, h, mode='full')
    m = conv.max()
    if m <= 0 or not np.isfinite(m):
        return 1e30, np.zeros_like(z)
    w = np.maximum(0.0, 1.0 - (m - conv) / (tol * m))
    tot = w.sum()
    if tot <= 0:
        w = np.zeros_like(conv)
        w[int(np.argmax(conv))] = 1.0
    else:
        w /= tot
    corr = fftconvolve(w, h[::-1], mode='full')
    start = N - 1
    grad_h = 2.0 * corr[start:start + N]
    grad_z = h * (grad_h - np.sum(grad_h * h))
    return m, grad_z


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() <= 0:
            s = np.ones_like(s)
    else:
        s = np.ones(30000)

    best_h = s / s.sum()
    if len(best_h) != 30000:
        best_h = _resample(best_h, 30000)
    best_C = _C_exact(best_h)
    print("start N=%d C=%.9f" % (len(best_h), best_C))

    # Refine at full resolution with the smooth max approximation.
    if time.process_time() < deadline:
        hf, Cf = _run_continuation(
            best_h, [51200, 204800, 819200, 3276800],
            deadline, maxiter=120)
        print("fine N=%d C=%.9f" % (len(hf), Cf))
        if Cf < best_C:
            best_h, best_C = hf, Cf

    # Active-set polishes with progressively smaller active bands.
    for tol in (1e-5, 1e-6, 1e-7):
        if time.process_time() < deadline:
            ha, Ca = _active_polish(best_h, deadline, maxiter=300, tol=tol)
            if Ca < best_C:
                best_h, best_C = ha, Ca
            print("active tol=%.0e N=%d C=%.9f" % (tol, len(best_h), best_C))

    # Final fine smooth polish.
    if time.process_time() < deadline:
        hp, Cp = _run_continuation(
            best_h, [3276800, 13107200], deadline, maxiter=100)
        if Cp < best_C:
            best_h, best_C = hp, Cp
        print("polish N=%d C=%.9f" % (len(best_h), best_C))

    best_C = _C_exact(best_h)
    print("final N=%d C=%.9f" % (len(best_h), best_C))
    return best_h

