import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds - 1.5  # margin

    # Start from a smooth bump. A Gaussian-like shape on the step grid.
    N = 30000
    x = (np.arange(N) + 0.5) / N - 0.5  # in [-0.5, 0.5] scaled; support full range
    # Use a broad, smooth positive bump. Try a raised cosine / parabolic shape.
    h = np.maximum(0.0, 1.0 - (2.0 * x) ** 2)
    # Actually we want support on [-1/4,1/4] of f; heights over full [-1/4,1/4] range.
    # x here is normalized; keep a smooth interior.

    def score(h):
        s = h.sum()
        if s <= 0:
            return 1e18
        c = np.convolve(h, h)
        return 2.0 * len(h) * c.max() / (s * s)

    # Also consider start if better
    best = h
    best_c = score(h)
    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.size > 0 and hs.size <= 30000 and hs.sum() > 0:
            cs = score(hs)
            if cs < best_c:
                best, best_c = hs, cs

    # Refine by trying a family of smooth profiles and pick the best.
    # The optimal f is believed to be a smooth "triangle-like" bump; try many shapes.
    def profile(kind, N, p):
        x = (np.arange(N) + 0.5) / N  # 0..1
        u = 2.0 * x - 1.0             # -1..1
        if kind == 0:
            return np.maximum(0.0, 1.0 - np.abs(u) ** p)
        if kind == 1:
            return np.cos(0.5 * np.pi * u) ** p
        if kind == 2:
            return np.maximum(0.0, (1.0 - u * u)) ** p
        if kind == 3:
            # truncated gaussian
            return np.exp(-p * u * u)
        if kind == 4:
            return np.maximum(0.0, 1.0 - u * u) * (1.0 + p * (1.0 - u * u))
        return np.ones(N)

    shapes = []
    for N in (200, 500, 1000, 2000, 4000, 8000):
        for kind in range(5):
            for p in (0.5, 0.75, 1.0, 1.25, 1.5, 2.0, 2.5, 3.0, 4.0):
                for _ in range(1):
                    shapes.append((kind, N, p))

    # Evaluate shapes but limit time
    for kind, N, p in shapes:
        if time.process_time() - t0 > budget * 0.6:
            break
        hh = profile(kind, N, p)
        if hh.sum() <= 0:
            continue
        c = score(hh)
        if c < best_c:
            best, best_c = hh, c

    # Local coordinate-wise refinement on the best, using multiplicative perturbations.
    # Only feasible for moderate N.
    if best.size <= 2000 and time.process_time() - t0 < budget * 0.8:
        h = best.astype(float)
        n = h.size
        step = 0.1
        improved = True
        while improved and time.process_time() - t0 < budget * 0.85:
            improved = False
            idxs = np.arange(n)
            # try perturbing each coordinate
            for i in range(n):
                if time.process_time() - t0 > budget * 0.85:
                    break
                old = h[i]
                for factor in (1.0 + step, 1.0 - step, 1.0 + 2*step, max(0.0, 1.0 - 2*step)):
                    h[i] = old * factor
                    c = score(h)
                    if c < best_c - 1e-12:
                        best_c = c
                        best = h.copy()
                        improved = True
                        break
                    h[i] = old
            step *= 0.6
            if step < 0.01:
                break

    return np.asarray(best, dtype=float)

