    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    def remaining():
        return deadline - time.process_time()

    # --- Candidate pool ---
    candidates = []

    # Known-good continuous family: f(x) ~ (1/4 - |x|) type / cosine bumps.
    # The classical extremiser is a "triangle-ish" bump. Try several smooth shapes.
    def make(kind, N, p):
        x = (np.arange(N) + 0.5) / N
        u = 2.0 * x - 1.0
        if kind == 0:
            return np.maximum(0.0, 1.0 - np.abs(u) ** p)
        if kind == 1:
            return np.cos(0.5 * np.pi * u) ** p
        if kind == 2:
            return np.maximum(0.0, (1.0 - u * u)) ** p
        if kind == 3:
            return np.exp(-p * u * u)
        if kind == 4:
            # triangle-like
            return np.maximum(0.0, 1.0 - np.abs(u))
        return np.ones(N)

    for N in (50, 100, 200, 400, 800, 1600):
        for kind in range(5):
            for p in (0.5, 1.0, 1.5, 2.0, 3.0):
                candidates.append(make(kind, N, p))

    # Include start
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            candidates.append(s.copy())

    # Pick best initial
    best = None
    bestC = np.inf
    for c in candidates:
        cc = C_of(c)
        if cc < bestC:
            bestC = cc
            best = c.copy()

    # --- Fine local refinement on small N (fast convolutions) ---
    # The optimal profile per N is smooth; small N already reaches low C.
    # Do coordinate descent in log-space with shrinking step, on the best candidate
    # resampled to a chosen working N.

    def refine(h, step0=0.05, min_step=1e-4):
        nonlocal bestC, best
        h = h.copy()
        Cc = C_of(h)
        if Cc < bestC:
            bestC, best = Cc, h.copy()
        step = step0
        n = h.size
        while remaining() > 0.2 and step > min_step:
            improved = False
            order = np.arange(n)
            for i in order:
                if remaining() <= 0.15:
                    break
                old = h[i]
                for sign in (1.0, -1.0):
                    h[i] = max(0.0, old * (1.0 + sign * step))
                    c = C_of(h)
                    if c < Cc - 1e-13:
                        Cc = c
                        improved = True
                        break
                    else:
                        h[i] = old
            if Cc < bestC:
                bestC, best = Cc, h.copy()
            if not improved:
                step *= 0.5
        return h, Cc

    # Refine at several scales; start from the best candidate resampled.
    base = best
    for workN in (50, 100, 200, 400, 800):
        if remaining() <= 0.3:
            break
        idx = np.linspace(0, base.size - 1, workN)
        h = np.interp(idx, np.arange(base.size), base)
        h = np.maximum(h, 0.0)
        h, _ = refine(h, step0=0.08, min_step=1e-4)
        if C_of(h) < bestC:
            bestC, best = C_of(h), h.copy()

    # --- Polish at the chosen N with fine steps ---
    if remaining() > 0.3:
        refine(best.copy(), step0=0.02, min_step=1e-5)

    return np.asarray(best, dtype=float)

