def _interp_knots(knots, N):
    xs = np.linspace(0.0, 1.0, len(knots))
    xi = (np.arange(N) + 0.5) / N
    return np.maximum(np.interp(xi, xs, knots), 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    # ---- Phase 1: differential evolution on 12 free knots, N=500 ----
    Ncoarse = 500
    K = 12

    def obj(knots):
        h = _interp_knots(knots, Ncoarse)
        if h.sum() <= 0:
            return 1e9
        return C_of(h)

    bounds = [(0.0, 1.0)] * K
    best_knots = None
    try:
        res = differential_evolution(
            obj, bounds, popsize=15, maxiter=200, seed=0,
            tol=1e-8, polish=False, init='latinhypercube',
            updating='immediate', workers=1,
        )
        best_knots = np.clip(res.x, 0.0, 1.0)
        de_C = res.fun
    except Exception:
        best_knots = np.ones(K)
        de_C = np.inf

    # ---- Phase 2: upsample to N=8000 and coordinate-ascent polish ----
    Nout = 8000
    h = _interp_knots(best_knots, Nout)
    Cc = C_of(h)
    best = h.copy()
    bestC = Cc

    # light smoothing to remove interp kinks before polish
    if h.size > 8:
        k = np.array([1.0, 2.0, 3.0, 2.0, 1.0]); k /= k.sum()
        hs = np.convolve(h, k, mode='same')
        cs = C_of(hs)
        if cs < Cc:
            h = hs; Cc = cs; best = h.copy(); bestC = cs

    step = 0.02
    while time.process_time() < deadline and step > 1e-5:
        improved = False
        # subsample indices for speed on large N
        stride = max(1, h.size // 2000)
        for i in range(0, h.size, stride):
            if time.process_time() >= deadline:
                break
            old = h[i]
            for sign in (1.0, -1.0):
                h[i] = max(0.0, old + sign * step * (1.0 + abs(old)))
                c = C_of(h)
                if c < Cc - 1e-12:
                    Cc = c
                    improved = True
                    break
                else:
                    h[i] = old
        if not improved:
            step *= 0.5

    if Cc < bestC:
        best = h
        bestC = Cc

    # ---- Compare with start ----
    if start is not None:
        s = np.asarray(start, dtype=float)
        if (s.ndim == 1 and s.size > 0 and s.size <= 30000
                and np.all(np.isfinite(s)) and s.sum() > 0):
            sc = C_of(s)
            if sc <= bestC:
                return s.copy()

    return np.maximum(best, 0.0)

