                if c < bestC:
                    bestC = c
                    best = hh.copy()

    if best is None:
        best = np.ones(50)
        bestC = score(best)

    # Coordinate descent in log-space. Use local convolution update trick:
    # we recompute full convolution each step (fast for small N).
    def refine(h, step0=0.05, min_step=1e-5, maxn=None):
