import numpy as np
import time
from scipy.optimize import minimize


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    if h.size == N:
        return h.copy()
    xs = (np.arange(h.size) + 0.5) / h.size
    xi = (np.arange(N) + 0.5) / N
    out = np.interp(xi, xs, h)
    return np.maximum(out, 0.0)


def _pnorm_obj(h, p):
    s = h.sum()
    if s <= 0:
        return 1e9
    c = np.convolve(h, h)
    c = np.maximum(c, 0.0)
    # (sum c^p)^(1/p) / s^2
    m = np.max(c)
    if m <= 0:
        return 1e9
    cn = c / m
    return m * (np.sum(cn ** p)) ** (1.0 / p) / (s * s)


def _pnorm_grad(h, p):
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    c = np.convolve(h, h)
    c = np.maximum(c, 0.0)
    m = np.max(c)
    if m <= 0:
        return np.zeros_like(h)
    cn = c / m
    # F = m * (sum cn^p)^(1/p) / s^2  -- treat m as constant (subgradient-ish)
    Sp = np.sum(cn ** p)
    if Sp <= 0:
        return np.zeros_like(h)
    P = Sp ** (1.0 / p)
    # dF/dc_k = m * (1/p) * Sp^(1/p - 1) * p * cn^(p-1) / m / s^2
    #         = cn^(p-1) / (P^(p-1)) / s^2   ... let's be careful
    # F = m * Sp^(1/p) / s^2 ; d/dc_k = m*(1/p)*Sp^(1/p-1)*p*cn^(p-1)*(1/m)/s^2
    #   = Sp^(1/p-1) * cn^(p-1) / s^2
    dFdc = (Sp ** (1.0 / p - 1.0)) * (cn ** (p - 1.0)) / (s * s)
    # gradient wrt h: conv of dFdc with h, both sides
    # d/dh_i sum_k dFdc_k * (h*h)_k = 2 * sum_k dFdc_k * h_{k-i}
    g = 2.0 * np.convolve(dFdc, h, mode='full')
    L = len(h)
    g = g[L - 1: 2 * L - 1]
    # minus term from denominator: F has 1/s^2, d/dh_i (1/s^2) = -2/s^3
    Fval = m * P / (s * s)
    g = g - Fval * 2.0 / s
    return g


def _coord_descent(h, deadline, max_stride_pts=2000):
    h = h.copy()
    Cc = C_of(h)
    best = h.copy()
