def _resample(h, N):
    h = np.asarray(h, dtype=float)
    if h.size == N:
        return h.copy()
    xs = (np.arange(h.size) + 0.5) / h.size
    xi = (np.arange(N) + 0.5) / N
    out = np.interp(xi, xs, h)
    return np.maximum(out, 0.0)


def _pnorm_obj(h, p):
    s = h.sum()
    if s <= 0:
        return 1e9
    c = np.convolve(h, h)
    c = np.maximum(c, 0.0)
    m = np.max(c)
    if m <= 0:
        return 1e9
    cn = c / m
    return m * (np.sum(cn ** p)) ** (1.0 / p) / (s * s)


def _pnorm_grad(h, p):
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    c = np.convolve(h, h)
    c = np.maximum(c, 0.0)
    m = np.max(c)
    if m <= 0:
        return np.zeros_like(h)
    cn = c / m
    Sp = np.sum(cn ** p)
    if Sp <= 0:
        return np.zeros_like(h)
    P = Sp ** (1.0 / p)
    dFdc = (Sp ** (1.0 / p - 1.0)) * (cn ** (p - 1.0)) / (s * s)
    g = 2.0 * np.convolve(dFdc, h, mode='full')
    L = len(h)
    g = g[L - 1: 2 * L - 1]
    Fval = m * P / (s * s)
    g = g - Fval * 2.0 / s
    return g


def _coord_descent(h, deadline, max_stride_pts=4000):
