                c = C_of(h)
                if c < Cc - 1e-12:
                    Cc = c
                    improved = True
                    break
                else:
                    h[i] = old
        if Cc < bestC:
            best = h.copy()
            bestC = Cc
        if not improved:
            step *= 0.5
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    # Build initial candidate
    has_start = False
    s_arr = None
    if start is not None:
