    else:
        h_init = np.ones(2000)
        Nout = 8000

    if h_init.sum() <= 0:
        h_init = np.ones(2000)
    h_init = h_init / h_init.sum()

    best_h = h_init.copy()
    bestC = C_of(_resample(h_init, Nout))

    # L-BFGS-B on p-norm objective; sweep p values
    for p in (6.0, 8.0, 10.0, 14.0):
        if time.process_time() >= deadline * 0.6:
            break
        def fun(x, pp=p):
            return _pnorm_obj(np.maximum(x, 0.0), pp)
        def jac(x, pp=p):
            return _pnorm_grad(np.maximum(x, 0.0), pp)
        try:
            res = minimize(fun, best_h, jac=jac, method='L-BFGS-B',
