            cand = np.maximum(res.x, 0.0)
            if cand.sum() > 0:
                candC = C_of(_resample(cand, Nout))
                if candC < bestC:
                    best_h = cand
                    bestC = candC
        except Exception:
            pass

    # Upsample best to Nout and coordinate-descent polish
    hN = _resample(best_h, Nout)
    if hN.size > 8:
        k = np.array([1.0, 2.0, 3.0, 2.0, 1.0]); k /= k.sum()
        hs = np.convolve(hN, k, mode='same')
