    return np.maximum(best_h_out, 0.0)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def C_and_grad_multi(h, delta):
    """C(h) and gradient averaged over all near-max convolution indices."""
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = fftconvolve(h, h, 'full')
    M = conv.max()
    if M <= 0:
        return np.inf, np.zeros(N)
    C = 2.0 * N * M / (S * S)
    active = np.where(conv >= M - delta * M)[0]
    grad = np.zeros(N)
    for m in active:
        lo = max(0, m - N + 1)
        hi = min(N - 1, m)
        idx = np.arange(lo, hi + 1)
        grad[idx] += 4.0 * N * h[m - idx] / (S * S) - 2.0 * C / S
    grad /= len(active)
    return C, grad


def _lbfgs_multi(h0, delta, maxiter=200):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)

    def fun(x):
        return C_and_grad_multi(x, delta)

    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       jac=True, options={'maxiter': maxiter,
                                          'maxfun': maxiter * 3,
                                          'ftol': 1e-15, 'gtol': 1e-12})
        xh = np.maximum(res.x, 0.0)
        return xh, C_of(xh)
    except Exception:
        return h, C_of(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is None:
        # fall back to a simple smooth bump
        N = 12000
        x = (np.arange(N) + 0.5) / N
        h = np.maximum(1.0 - np.abs(2 * x - 1), 0.0)
        return h

    s = np.asarray(start, dtype=float)
    if not (s.ndim == 1 and 0 < s.size <= 30000
            and np.all(np.isfinite(s)) and s.sum() > 0):
        return s
    s = np.maximum(s, 0.0)

    best = s.copy()
    bestC = C_of(s)

    for delta in (0.0, 1e-8, 1e-6, 1e-4):
        if time.process_time() >= deadline:
            break
        xh, c = _lbfgs_multi(best, delta, maxiter=200)
        if c < bestC - 1e-14:
            best = xh
            bestC = c

    # final safety: return start if no improvement
    if bestC >= C_of(s):
        return s.copy()
    return np.maximum(best, 0.0)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
