def _resample(h, N):
    h = np.asarray(h, dtype=float)
    if h.size == N:
        return h.copy()
    xs = (np.arange(h.size) + 0.5) / h.size
    xi = (np.arange(N) + 0.5) / N
    return np.maximum(np.interp(xi, xs, h), 0.0)


def _pnorm_obj(h, p):
    s = h.sum()
    if s <= 0:
        return 1e9
    c = np.maximum(np.convolve(h, h), 0.0)
    m = c.max()
    if m <= 0:
        return 1e9
    cn = c / m
    return m * np.sum(cn ** p) ** (1.0 / p) / (s * s)


def _pnorm_grad(h, p):
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    c = np.maximum(np.convolve(h, h), 0.0)
    m = c.max()
    if m <= 0:
        return np.zeros_like(h)
    cn = c / m
    Sp = np.sum(cn ** p)
    if Sp <= 0:
        return np.zeros_like(h)
    dFdc = (Sp ** (1.0 / p - 1.0)) * (cn ** (p - 1.0)) / (s * s)
    g = 2.0 * np.convolve(dFdc, h, mode='full')
    L = len(h)
    g = g[L - 1: 2 * L - 1]
    Fval = m * Sp ** (1.0 / p) / (s * s)
    return g - Fval * 2.0 / s


def _smooth_max_obj_grad(h, beta):
    """log-sum-exp smoothed max; returns C-like value and gradient."""
    h = np.asarray(h, dtype=float)
    N = len(h)
    s = h.sum()
    if s <= 0:
        return np.inf, np.zeros(N)
    c = np.convolve(h, h)
    c = np.maximum(c, 0.0)
    m = c.max()
    if m <= 0:
        return np.inf, np.zeros(N)
    w = np.exp(beta * (c - m))
    Z = w.sum()
    logZ = np.log(Z)
    softmax_val = m + logZ / beta
    val = 2.0 * N * softmax_val / (s * s)
    w = w / Z
    dSdc = w  # derivative of softmax_val wrt c
    g = 2.0 * np.convolve(dSdc, h, mode='full') * (2.0 * N / (s * s))
    L = N
    g = g[L - 1: 2 * L - 1]
    g = g - val * 2.0 / s
    return val, g


def _lbfgs_pnorm(h0, p, maxiter, deadline):
    def fun(x):
        return _pnorm_obj(np.maximum(x, 0.0), p)

    def jac(x):
        return _pnorm_grad(np.maximum(x, 0.0), p)

    try:
        res = minimize(fun, h0, jac=jac, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-12})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h0


def _lbfgs_smooth(h0, beta, maxiter):
    def fun(x):
        v, g = _smooth_max_obj_grad(np.maximum(x, 0.0), beta)
        return v, g

    try:
        res = minimize(fun, h0, method='L-BFGS-B', jac=True,
                       bounds=[(0.0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h0


def _coord_descent(h, deadline, max_stride_pts=6000):
    h = h.copy()
    Cc = C_of(h)
    best, bestC = h.copy(), Cc
    step = 0.01
    while time.process_time() < deadline and step > 1e-7:
        improved = False
        stride = max(1, h.size // max_stride_pts)
        for i in range(0, h.size, stride):
            if time.process_time() >= deadline:
                break
            old = h[i]
            for sign in (1.0, -1.0):
                h[i] = max(0.0, old + sign * step * (1.0 + abs(old)))
                c = C_of(h)
                if c < Cc - 1e-13:
                    Cc = c
                    improved = True
                    break
                h[i] = old
        if Cc < bestC:
            best, bestC = h.copy(), Cc
        if not improved:
            step *= 0.5
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    has_start = False
    s_arr = None
    if start is not None:
        s_arr = np.asarray(start, dtype=float)
        if (s_arr.ndim == 1 and 0 < s_arr.size <= 30000
                and np.all(np.isfinite(s_arr)) and s_arr.sum() > 0):
            has_start = True

    if has_start:
        s_arr = np.maximum(s_arr, 0.0)
        bestC_start = C_of(s_arr)
        # Work at the same resolution as start (avoid resampling loss)
        Nwork = s_arr.size
        h_init = s_arr / s_arr.sum()
        best_h = s_arr.copy()
        bestC = bestC_start
    else:
        Nwork = 4000
        x = (np.arange(Nwork) + 0.5) / Nwork
        h_init = np.maximum(1.0 - np.abs(2 * x - 1), 0.0)
        h_init = h_init / h_init.sum()
        best_h = h_init.copy()
        bestC = C_of(h_init)

    # Stage 1: smoothed-max L-BFGS with decreasing beta
    for beta in (30.0, 100.0, 300.0, 1000.0):
        if time.process_time() >= deadline * 0.55:
            break
        cand = _lbfgs_smooth(best_h, beta, maxiter=120)
        if cand.sum() > 0:
            cc = C_of(cand)
            if cc < bestC - 1e-14:
                best_h, bestC = cand, cc

    # Stage 2: p-norm sweep
    for p in (8.0, 12.0, 20.0, 40.0):
        if time.process_time() >= deadline * 0.75:
            break
        cand = _lbfgs_pnorm(best_h, p, maxiter=100, deadline=deadline)
        if cand.sum() > 0:
            cc = C_of(cand)
            if cc < bestC - 1e-14:
                best_h, bestC = cand, cc

    # Stage 3: coordinate-descent polish
    polished, polC = _coord_descent(best_h, deadline)
    if polC < bestC:
        best_h, bestC = polished, polC

    if has_start and bestC_start <= bestC:
        return s_arr.copy()
    return np.maximum(best_h, 0.0)

import numpy as np
import time
from scipy.optimize import minimize


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    xs = np.linspace(0.0, 1.0, len(h))
    xi = (np.arange(N) + 0.5) / N
    return np.maximum(np.interp(xi, xs, h), 0.0)


def _Cp_and_grad(h, p):
    """p-norm smooth surrogate for max of convolution, with gradient."""
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.maximum(np.convolve(h, h), 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    w = (conv / mx) ** p
    sump = (mx ** p) * w.sum()
    if sump <= 0:
        return np.inf, np.zeros(N)
    Cp = 2.0 * N * (sump ** (1.0 / p)) / (S * S)
    pref = (sump ** (1.0 / p)) / sump
    dconv = pref * (conv ** (p - 1))
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cp / S
    return Cp, grad


def _polish(h0, deadline, p=None, maxiter=200):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    best = h.copy()
    bestC = C_of(h)
