def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    best = None
    bestC = np.inf

    # Seed from start (strongest known), else from a gaussian-ish bump
    if start is not None:
        s = np.asarray(start, dtype=float)
        if (s.ndim == 1 and s.size > 0 and s.size <= 30000
                and np.all(np.isfinite(s)) and s.sum() > 0):
            best = s.copy()
            bestC = C_of(best)

    if best is None:
        N0 = 2000
        x = (np.arange(N0) + 0.5) / N0
        best = np.exp(-((x - 0.5) ** 2) / 0.02)
        bestC = C_of(best)

    # Work at a fixed high resolution; polish with p-norm sequence then true C.
    # Upsample start to N=6000 for a good working resolution.
    Nwork = 6000
    h = _resample(best, Nwork)
    c = C_of(h)
    if c < bestC:
        best, bestC = h.copy(), c
    else:
        h = best.copy()

    # p-norm smoothing sequence to escape argmax kinks (multi-active peaks)
    for p in (4, 16, 64, 256):
        if time.process_time() >= deadline:
            break
        h2, c2 = _polish(h, deadline, p=p, maxiter=120)
        if c2 < C_of(h):
            h = h2
        if c2 < bestC:
            best, bestC = h2.copy(), c2

    # True-C polish (argmax gradient) to squeeze the exact objective
    for _ in range(6):
        if time.process_time() >= deadline:
            break
        h2, c2 = _polish(h, deadline, p=None, maxiter=200)
        improved = c2 < C_of(h)
        if improved:
            h = h2
        if c2 < bestC:
            best, bestC = h2.copy(), c2
        if not improved:
            break

    # Try upsampling to N=12000 and re-polishing for finer resolution gains
    if time.process_time() < deadline:
        h = _resample(best, 12000)
        c = C_of(h)
        if c < bestC:
