def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad(h):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (S * S)
    grad = np.zeros(N)
    lo = max(0, m - N + 1)
    hi = min(N - 1, m)
    idx = np.arange(lo, hi + 1)
    grad[idx] = 4.0 * N * h[m - idx] / (S * S) - 2.0 * C / S
    return C, grad


def _C_lse_and_grad(h, tau):
    """Log-sum-exp max objective: 2N*tau*log(sum exp(conv/tau))/S^2."""
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    if tau <= 0:
        tau = 1e-12 * max(mx, 1e-300)
    z = (conv - mx) / tau
    # log-sum-exp stable
    e = np.exp(z)
    se = e.sum()
    lse = mx + tau * np.log(se)
    C = 2.0 * N * lse / (S * S)
    # d lse / d conv_j = e_j / se
    w = e / se
    # grad wrt h: conv = h*h ; d/dh[i] = 2 * sum_k w[k] h[k-i]
    full = np.convolve(w, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * C / S
    return C, grad


def _lbfgs(h0, deadline, maxiter, p=None, tau=None):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    best = h.copy()
    bestC = C_of(h)

    if tau is not None:
        def fun(x):
            return _C_lse_and_grad(x, tau)
    elif p is not None:
        def fun(x):
            return _Cp_and_grad(x, p)
    else:
        def fun(x):
            return _C_and_grad(x)

    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                          'ftol': 1e-15, 'gtol': 1e-12})
        xh = np.maximum(res.x, 0.0)
        c = C_of(xh)
        if c < bestC:
            best = xh
            bestC = c
    except Exception:
        pass
    return best, bestC


def _Cp_and_grad(h, p):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.maximum(np.convolve(h, h), 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    w = (conv / mx) ** p
    sw = w.sum()
    if sw <= 0:
        return np.inf, np.zeros(N)
    sump = (mx ** p) * sw
    Cp = 2.0 * N * (sump ** (1.0 / p)) / (S * S)
    pref = (sump ** (1.0 / p)) / sump
    dconv = pref * (conv ** (p - 1))
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cp / S
    return Cp, grad


