        conv = np.convolve(best, best)
        mx = conv.max()
        tau = frac * mx
        b2, c2 = _lbfgs(best, deadline, maxiter=80, tau=tau)
        if c2 < bestC:
            best = b2
            bestC = c2

    # True-C polish
    if time.process_time() < deadline:
        b2, c2 = _lbfgs(best, deadline, maxiter=60, p=None)
