    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (S * S)
    grad = np.zeros(N)
    lo = max(0, m - N + 1)
    hi = min(N - 1, m)
    idx = np.arange(lo, hi + 1)
    grad[idx] = 4.0 * N * h[m - idx] / (S * S) - 2.0 * C / S
    return C, grad


def _Cp_and_grad(h, p):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.maximum(np.convolve(h, h), 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    w = (conv / mx) ** p
    sw = w.sum()
    if sw <= 0:
        return np.inf, np.zeros(N)
    sump = (mx ** p) * sw
    Cp = 2.0 * N * (sump ** (1.0 / p)) / (S * S)
    pref = (sump ** (1.0 / p)) / sump
    dconv = pref * (conv ** (p - 1))
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cp / S
    return Cp, grad


def _resample(h, Nnew):
    xs = np.linspace(0.0, 1.0, len(h))
    xi = (np.arange(Nnew) + 0.5) / Nnew
    return np.maximum(np.interp(xi, xs, h), 0.0)


def _lbfgs(h0, maxiter=200, p=None):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    best, bestC = h.copy(), C_of(h)
    fun = _C_and_grad if p is None else (lambda x: _Cp_and_grad(x, p))
    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-13})
        xh = np.maximum(res.x, 0.0)
        c = C_of(xh)
        if c < bestC:
            best, bestC = xh, c
    except Exception:
        pass
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0

    def remaining():
        return deadline - time.process_time()

    best = None
    bestC = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            best, bestC = s.copy(), C_of(s)

    if best is None:
        N = 400
        x = (np.arange(N) + 0.5) / N
        u = 2.0 * x - 1.0
        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    work = best.copy()
    Cw = bestC

    # Upsample first to a fine grid, then refine with p-norm smoothing.
    # Fine grid gives finer control over the flat top of f*f.
    for Nnew in (2000, 4000, 8000, 12000, 16000):
        if remaining() < 0.8:
            break
        h = _resample(work, Nnew) if Nnew != work.size else work.copy()
        for p in (24, 96):
            if remaining() < 0.5:
                break
            hp, cp = _lbfgs(h, maxiter=80, p=p)
            if cp < C_of(h):
                h = hp
        h, c = _lbfgs(h, maxiter=200, p=None)
        if c < Cw:
            Cw, work = c, h.copy()
        if c < bestC:
            bestC, best = c, h.copy()

    # Extra p-norm sweeps at the finest grid to escape argmax stalls.
    if remaining() > 0.4:
        Nfin = work.size
        h = work.copy()
        for p in (8, 32, 128, 512):
            if remaining() < 0.3:
                break
            hp, cp = _lbfgs(h, maxiter=80, p=p)
            if cp < C_of(h):
                h = hp
            h, c = _lbfgs(h, maxiter=150, p=None)
            if c < bestC:
                bestC, best = c, h.copy()

    return np.maximum(np.asarray(best, dtype=float), 0.0)

