        else:
            base = np.ones(4000)
    else:
        base = np.ones(4000)

    # Downsample base to N=2500
    Nc = 2500
    coarse = _downsample(base, Nc)
    coarseC = C_of(coarse)

    # Random Fourier restarts on coarse grid
    rng = np.random.default_rng(12345)
    x = (np.arange(Nc) + 0.5) / Nc
    best_coarse = coarse.copy()
    best_coarseC = coarseC

    ks = [1, 2, 3, 5]
    amps = [0.2, 0.5]
    trials = []
    for k in ks:
        for a in amps:
            phi = rng.uniform(0, 2 * np.pi)
            trials.append((k, a, phi))
    # add a couple more with random k
    for _ in range(4):
        k = int(rng.integers(1, 6))
        a = float(rng.uniform(0.1, 0.6))
        phi = rng.uniform(0, 2 * np.pi)
        trials.append((k, a, phi))

