        mx = conv.max()
        b, c = _lbfgs(h0, maxiter=60, tau=1e-2 * mx)
        if time.process_time() >= deadline:
            if c < best_coarseC:
                best_coarse, best_coarseC = b, c
            break
        # true-C polish
        b2, c2 = _lbfgs(b, maxiter=60, p=None)
        if c2 < best_coarseC:
            best_coarse = b2
            best_coarseC = c2

    # Upsample best coarse to N=10000
    Nout = 10000
    h = _upsample(best_coarse, Nout)
    best = h.copy()
    bestC = C_of(h)

