        if c2 < bestC:
            best = b2
            bestC = c2

    if time.process_time() < deadline:
        b2, c2 = _lbfgs(best, maxiter=120, p=None)
        if c2 < bestC:
            best = b2
            bestC = c2

    if start is not None:
        s = np.asarray(start, dtype=float)
