    se = e.sum()
    lse = mx + tau * np.log(se)
    C = 2.0 * N * lse / (S * S)
    w = e / se
    full = np.convolve(w, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * C / S
    return C, grad


def _lbfgs_deadline(h0, deadline, maxiter, tau=None):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    state = {'best': h.copy(), 'bestC': C_of(h)}

    def fun(x):
        return _C_lse_and_grad(x, tau)

    def callback(xk):
        if time.process_time() >= deadline:
            raise StopIteration
        xh = np.maximum(np.asarray(xk, dtype=float), 0.0)
        c = C_of(xh)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xh.copy()

    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       jac=True, callback=callback,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-16, 'gtol': 1e-13})
        xh = np.maximum(res.x, 0.0)
        c = C_of(xh)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xh.copy()
    except StopIteration:
        pass
    except Exception:
        pass

    return state['best'], state['bestC']


def _refine_local(h, deadline, rounds=3):
    """Small direct coordinate-descent style polish around the peak."""
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    best = h.copy()
    bestC = C_of(h)
    N = len(best)
    for _ in range(rounds):
        if time.process_time() >= deadline:
            break
        conv = np.convolve(best, best)
        m = int(np.argmax(conv))
        # window of indices contributing to peak
        lo = max(0, m - N + 1)
        hi = min(N - 1, m)
        improved = False
        # nudge a few coords near the peak-support region
        center = (lo + hi) // 2
        width = max(1, (hi - lo) // 4)
        cand_idx = np.arange(max(0, center - width), min(N, center + width + 1))
        for i in cand_idx:
            if time.process_time() >= deadline:
                break
            for factor in (1.02, 0.98):
                trial = best.copy()
                trial[i] *= factor
                c = C_of(trial)
                if c < bestC - 1e-12:
                    best = trial
                    bestC = c
                    improved = True
        if not improved:
            break
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        s = np.asarray(start, dtype=float)
        if (s.ndim == 1 and s.size > 0 and s.size <= 30000
                and np.all(np.isfinite(s)) and s.sum() > 0):
            base = np.maximum(s, 0.0)
        else:
            base = np.ones(4000)
    else:
        base = np.ones(4000)

    Nout = 12000
    xs = np.linspace(0.0, 1.0, len(base))
    xi = (np.arange(Nout) + 0.5) / Nout
    h = np.maximum(np.interp(xi, xs, base), 0.0)

    best = h.copy()
    bestC = C_of(h)

    for frac in (1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5):
        if time.process_time() >= deadline:
            break
        conv = np.convolve(best, best)
        mx = conv.max()
        tau = frac * mx
        b2, c2 = _lbfgs_deadline(best, deadline, maxiter=120, tau=tau)
        if c2 < bestC:
            best = b2
            bestC = c2

    # final local polish with a very small tau
    if time.process_time() < deadline:
        conv = np.convolve(best, best)
        tau = 1e-6 * conv.max()
        b2, c2 = _lbfgs_deadline(best, deadline, maxiter=120, tau=tau)
        if c2 < bestC:
            best = b2
            bestC = c2

    if time.process_time() < deadline:
        b2, c2 = _refine_local(best, deadline, rounds=2)
        if c2 < bestC:
            best = b2
            bestC = c2

    if start is not None:
        s = np.asarray(start, dtype=float)
        if (s.ndim == 1 and s.size > 0 and s.size <= 30000
                and np.all(np.isfinite(s)) and s.sum() > 0):
            if C_of(s) <= bestC:
                return s.copy()

    return np.maximum(best, 0.0)

