def _smooth_plateau(h, iterations=30, step=0.02):
    """Local smoothing near the argmax to flatten the plateau of f*f."""
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    best = h.copy()
    bestC = C_of(h)
    rng = np.random.default_rng(12345)
    for _ in range(iterations):
        conv = np.convolve(h, h)
        m = int(np.argmax(conv))
        # knots near max
        lo = max(0, m - N + 1)
        hi = min(N - 1, m)
        idx = np.arange(lo, hi + 1)
        # find knots close to max
        mask = conv[idx] > 0.999 * conv[m]
        near = idx[mask]
        if near.size == 0:
            break
        # try perturbing heights near the support of those knots
        trial = h.copy()
        for _ in range(3):
            j = int(rng.integers(0, N))
            k = int(rng.integers(0, N))
            if trial[j] > 0 and trial[k] > 0:
                delta = step * trial[j] * (rng.random() - 0.5)
                trial[j] = max(0.0, trial[j] + delta)
                trial[k] = max(0.0, trial[k] - delta * trial[j] / max(trial[k], 1e-12) if trial[k] > 0 else trial[k])
        c = C_of(trial)
        if c < bestC:
            best, bestC = trial, c
            h = trial
    return best, bestC


