    if best is None:
        N = 400
        x = (np.arange(N) + 0.5) / N
        u = 2.0 * x - 1.0
        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    work = best.copy()
    Cw = bestC

    # Refine at current grid first (cheap), then upsample.
    for Nnew in (work.size, 4000, 8000, 12000):
        if remaining() < 1.0:
            break
        if Nnew != work.size:
            h = _resample(work, Nnew)
        else:
            h = work.copy()
        for p in (16, 64, 256):
            if remaining() < 0.6:
                break
            hp, cp = _lbfgs(h, maxiter=70, p=p)
            if cp < C_of(h):
                h = hp
        h, c = _lbfgs(h, maxiter=200, p=None)
        if c < Cw:
            Cw, work = c, h.copy()
        if c < bestC:
            bestC, best = c, h.copy()

    # Plateau-flattening random perturbations at the fine grid.
    if remaining() > 0.5:
        h = work.copy()
        for _ in range(4):
            if remaining() < 0.4:
                break
            hs, cs = _smooth_plateau(h, iterations=25, step=0.03)
            if cs < C_of(h):
                h = hs
            h, c = _lbfgs(h, maxiter=120, p=None)
            if c < bestC:
                bestC, best = c, h.copy()

    # Final alternating p-norm escape.
    if remaining() > 0.4:
        h = best.copy()
        for p in (8, 32, 128):
            if remaining() < 0.3:
                break
            hp, cp = _lbfgs(h, maxiter=60, p=p)
            if cp < C_of(h):
                h = hp
            h, c = _lbfgs(h, maxiter=120, p=None)
            if c < bestC:
                bestC, best = c, h.copy()

    return np.maximum(np.asarray(best, dtype=float), 0.0)

