    lse = mx + tau * np.log(se)
    C = 2.0 * N * lse / (S * S)
    w = e / se
    full = np.convolve(w, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * C / S
    return C, grad


def _lbfgs(h0, maxiter, p=None, tau=None, eps=None, frac=None):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    best = h.copy()
    bestC = C_of(h)

    if eps is not None:
        def fun(x):
            return _Ctopk_and_grad(x, eps)
    elif frac is not None:
        def fun(x):
            return _Clse_and_grad(x, frac)
    elif tau is not None:
        def fun(x):
            return _C_lse_and_grad(x, tau)
    elif p is not None:
        def fun(x):
            return _Cp_and_grad(x, p)
    else:
        def fun(x):
            return _C_and_grad(x)

    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       jac=True, options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                          'ftol': 1e-15, 'gtol': 1e-12})
        xh = np.maximum(res.x, 0.0)
        c = C_of(xh)
        if c < bestC:
            best = xh
            bestC = c
    except Exception:
        pass
    return best, bestC


def _fourier_to_h(coef, N0):
    a = coef[:8]
    b = coef[8:15]
    x = (np.arange(N0) + 0.5) / N0
    logh = np.full(N0, a[0])
    for k in range(1, 8):
        logh = logh + a[k] * np.cos(2 * np.pi * k * x)
    for k in range(1, 8):
        logh = logh + b[k - 1] * np.sin(2 * np.pi * k * x)
    logh = logh - logh.max()
    return np.exp(logh)


def _fourier_score(coef, N0):
    h = _fourier_to_h(coef, N0)
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 1e6
    return C_of(h)


def _fourier_prestage(N0=200, n_draws=400, n_keep=5, nm_iter=400, rng=None):
    if rng is None:
        rng = np.random.default_rng(12345)
    draws = rng.standard_normal((n_draws, 15))
    draws[:, 0] = 0.0
    scores = np.empty(n_draws)
    for i in range(n_draws):
        scores[i] = _fourier_score(draws[i], N0)
    order = np.argsort(scores)
    top = draws[order[:n_keep]]
    best_coef = top[0].copy()
    best_score = scores[order[0]]
    for c0 in top:
        try:
            res = minimize(lambda c: _fourier_score(c, N0), c0,
                           method='Nelder-Mead',
                           options={'maxiter': nm_iter, 'xatol': 1e-6,
                                    'fatol': 1e-9})
            sc = _fourier_score(res.x, N0)
            if sc < best_score:
                best_score = sc
                best_coef = res.x.copy()
        except Exception:
            pass
    return best_coef, best_score


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        s = np.asarray(start, dtype=float)
        if (s.ndim == 1 and s.size > 0 and s.size <= 30000
                and np.all(np.isfinite(s)) and s.sum() > 0):
            base = np.maximum(s, 0.0)
        else:
            base = np.ones(4000)
    else:
        base = np.ones(4000)

    fourier_best = None
    try:
        if time.process_time() < deadline:
            coef, fscore = _fourier_prestage(N0=200, n_draws=400, n_keep=5,
                                             nm_iter=400)
            h200 = _fourier_to_h(coef, 200)
            xs = (np.arange(200) + 0.5) / 200
            xi = (np.arange(800) + 0.5) / 800
            h800 = np.maximum(np.interp(xi, xs, h200), 0.0)
            if h800.sum() > 0:
                fourier_best = h800
    except Exception:
        fourier_best = None

    Nout = 8000
    xs = np.linspace(0.0, 1.0, len(base))
    xi = (np.arange(Nout) + 0.5) / Nout
    h = np.maximum(np.interp(xi, xs, base), 0.0)

    best = h.copy()
    bestC = C_of(h)

    fracs = np.geomspace(5e-2, 1e-6, 12)
    for frac in fracs:
        if time.process_time() >= deadline:
            break
        conv = np.convolve(best, best)
        mx = conv.max()
        tau = float(frac) * mx
        b2, c2 = _lbfgs(best, maxiter=45, tau=tau)
        if c2 < bestC:
            best = b2
            bestC = c2

    if time.process_time() < deadline:
        b2, c2 = _lbfgs(best, maxiter=150, p=None)
        if c2 < bestC:
            best = b2
            bestC = c2

    if fourier_best is not None and time.process_time() < deadline:
        xs2 = np.linspace(0.0, 1.0, len(fourier_best))
        hf = np.maximum(np.interp(xi, xs2, fourier_best), 0.0)
        fbest = hf.copy()
        fbestC = C_of(hf)
        for frac in fracs:
            if time.process_time() >= deadline:
                break
            conv = np.convolve(fbest, fbest)
            mx = conv.max()
            tau = float(frac) * mx
            b2, c2 = _lbfgs(fbest, maxiter=45, tau=tau)
            if c2 < fbestC:
                fbest = b2
                fbestC = c2
        if time.process_time() < deadline:
            b2, c2 = _lbfgs(fbest, maxiter=150, p=None)
            if c2 < fbestC:
                fbest = b2
                fbestC = c2
        if fbestC < bestC:
            best = fbest
            bestC = fbestC

    # --- New: top-k / LSE polishing at N=3000 ---
    if time.process_time() < deadline:
        Np = 3000
        xsp = np.linspace(0.0, 1.0, len(best))
        xip = (np.arange(Np) + 0.5) / Np
        hp = np.maximum(np.interp(xip, xsp, best), 0.0)
        pbest = hp.copy()
        pbestC = C_of(hp)
        for eps in (1e-3, 3e-4, 1e-4):
            if time.process_time() >= deadline:
                break
            b2, c2 = _lbfgs(pbest, maxiter=80, eps=eps)
            if c2 < pbestC:
                pbest = b2
                pbestC = c2
        for frac in (1e-3, 3e-4, 1e-4, 3e-5):
            if time.process_time() >= deadline:
                break
            b2, c2 = _lbfgs(pbest, maxiter=80, frac=frac)
            if c2 < pbestC:
                pbest = b2
                pbestC = c2
        if time.process_time() < deadline:
            b2, c2 = _lbfgs(pbest, maxiter=150, p=None)
            if c2 < pbestC:
                pbest = b2
                pbestC = c2
        if pbestC < bestC:
            best = pbest
            bestC = pbestC

    if start is not None:
        s = np.asarray(start, dtype=float)
        if (s.ndim == 1 and s.size > 0 and s.size <= 30000
                and np.all(np.isfinite(s)) and s.sum() > 0):
            if C_of(s) <= bestC:
                return s.copy()

    return np.maximum(best, 0.0)

import numpy as np
import time
from scipy.optimize import minimize


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad(h):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (S * S)
    grad = np.zeros(N)
    lo = max(0, m - N + 1)
    hi = min(N - 1, m)
    idx = np.arange(lo, hi + 1)
    grad[idx] = 4.0 * N * h[m - idx] / (S * S) - 2.0 * C / S
    return C, grad


def _Ctopk_and_grad(h, eps):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    conv = np.maximum(conv, 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    thr = (1.0 - eps) * mx
    w = (conv >= thr).astype(float)
    sw = w.sum()
    if sw <= 0:
        return np.inf, np.zeros(N)
    w /= sw
    Ctop = 2.0 * N * float(np.sum(w * conv)) / (S * S)
    full = np.convolve(w, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Ctop / S
    return Ctop, grad


def _Cp_and_grad(h, p):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    conv = np.maximum(conv, 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    w = (conv / mx) ** p
    sw = w.sum()
    if sw <= 0:
        return np.inf, np.zeros(N)
    sump = (mx ** p) * sw
    Cp = 2.0 * N * (sump ** (1.0 / p)) / (S * S)
    pref = (sump ** (1.0 / p)) / sump
    dconv = pref * (conv ** (p - 1))
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cp / S
    return Cp, grad


def _Clse_and_grad(h, tau):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    conv = np.maximum(conv, 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    tau = max(tau, 1e-12 * max(mx, 1e-30))
    z = (conv - mx) / tau
    e = np.exp(z)
    se = e.sum()
    lse = mx + tau * np.log(se)
    Cl = 2.0 * N * lse / (S * S)
    dconv = e / se
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cl / S
    return Cl, grad


def _resample(h, Nnew):
    xs = np.linspace(0.0, 1.0, len(h))
    xi = (np.arange(Nnew) + 0.5) / Nnew
    return np.maximum(np.interp(xi, xs, h), 0.0)


def _lbfgs(h0, maxiter=200, p=None, tau=None, eps=None):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    best, bestC = h.copy(), C_of(h)
    if eps is not None:
        fun = lambda x: _Ctopk_and_grad(x, eps)
    elif p is not None:
        fun = lambda x: _Cp_and_grad(x, p)
    elif tau is not None:
        fun = lambda x: _Clse_and_grad(x, tau)
    else:
        fun = _C_and_grad
    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-13})
        xh = np.maximum(res.x, 0.0)
        c = C_of(xh)
        if c < bestC:
            best, bestC = xh, c
    except Exception:
        pass
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.88 * budget_seconds

    def remaining():
        return deadline - time.process_time()

    best = None
    bestC = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            best, bestC = s.copy(), C_of(s)

    if best is None:
        N = 200
        x = (np.arange(N) + 0.5) / N
        u = 2.0 * x - 1.0
        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    work = best.copy()
    Cw = bestC
    for Nnew in (300, 800, 1500, 3000, 6000, 12000):
        if remaining() < 0.6:
            break
        h = _resample(work, Nnew) if Nnew != work.size else work.copy()
        for p in (16, 64):
            if remaining() < 0.4:
                break
            hp, cp = _lbfgs(h, maxiter=60, p=p)
            if cp < C_of(h):
                h = hp
        for eps in (1e-3, 3e-4):
            if remaining() < 0.35:
                break
            ht, ct = _lbfgs(h, maxiter=50, eps=eps)
            if ct < C_of(h):
                h = ht
        for frac in (1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5):
            if remaining() < 0.3:
                break
            conv = np.convolve(h, h)
            mx = conv.max()
            tau = frac * mx
            hl, cl = _lbfgs(h, maxiter=50, tau=tau)
            if cl < C_of(h):
                h = hl
        h, c = _lbfgs(h, maxiter=200, p=None)
        if c < Cw:
            Cw, work = c, h.copy()
        if c < bestC:
            bestC, best = c, h.copy()

    # Experiment: longer, colder LSE ladder directly on the N=3000 best.
    if best.size == 3000 and remaining() > 0.5:
        h = best.copy()
        for frac in (3e-5, 1e-5, 3e-6, 1e-6):
            if remaining() < 0.4:
                break
            conv = np.convolve(h, h)
            mx = conv.max()
            hl, cl = _lbfgs(h, maxiter=150, tau=frac * mx)
            if cl < C_of(h):
                h = hl
        if remaining() > 0.3:
            ht, ct = _lbfgs(h, maxiter=100, eps=1e-4)
            if ct < C_of(h):
                h = ht
        if remaining() > 0.25:
            h, c = _lbfgs(h, maxiter=300, p=None)
        else:
            c = C_of(h)
        if c < bestC:
            bestC, best = c, h.copy()

    if remaining() > 0.3:
        Nfin = min(12000, max(work.size, 12000))
        h = _resample(work, Nfin)
        for eps in (1e-3, 3e-4):
            if remaining() < 0.3:
                break
            ht, ct = _lbfgs(h, maxiter=50, eps=eps)
            if ct < C_of(h):
                h = ht
        for frac in (1e-3, 3e-4, 1e-4, 3e-5):
            if remaining() < 0.3:
                break
            conv = np.convolve(h, h)
            mx = conv.max()
            hl, cl = _lbfgs(h, maxiter=50, tau=frac * mx)
            if cl < C_of(h):
                h = hl
        h, c = _lbfgs(h, maxiter=120, p=None)
        if c < bestC:
            bestC, best = c, h.copy()

    return np.maximum(np.asarray(best, dtype=float), 0.0)

