        c = C_of(xh)
        if c < bestC:
            best, bestC = xh, c
    except Exception:
        pass
    return best, bestC


def _refine(h, remaining, maxiter=250):
    conv = np.convolve(h, h)
    mx = conv.max()
    for eps in (1e-3, 3e-4):
        if remaining() < 0.3:
            break
        ht, ct = _lbfgs(h, maxiter=50, eps=eps)
        if ct < C_of(h):
            h = ht
    for p in (16, 64):
        if remaining() < 0.3:
            break
        hp, cp = _lbfgs(h, maxiter=60, p=p)
        if cp < C_of(h):
            h = hp
    for frac in (1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5):
        if remaining() < 0.3:
            break
        conv = np.convolve(h, h)
        mx = conv.max()
        hl, cl = _lbfgs(h, maxiter=50, tau=frac * mx)
        if cl < C_of(h):
            h = hl
    h, c = _lbfgs(h, maxiter=maxiter, p=None)
    return h, c


def _perturb(h, rng, strength=0.05):
    """Multiplicative smooth perturbation to escape local basin."""
    N = len(h)
    x = np.linspace(0, 1, N)
    log_m = np.zeros(N)
    for k in range(1, 6):
        a = rng.standard_normal() * strength
        b = rng.standard_normal() * strength
        log_m += a * np.cos(2 * np.pi * k * x) + b * np.sin(2 * np.pi * k * x)
    return np.maximum(h * np.exp(log_m), 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.85 * budget_seconds

    def remaining():
        return deadline - time.process_time()

    best = None
    bestC = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            best, bestC = s.copy(), C_of(s)

    if best is None:
        N = 200
        x = (np.arange(N) + 0.5) / N
        u = 2.0 * x - 1.0
        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    work = best.copy()
    Cw = bestC

    # Multi-scale refinement ladder (same as p0154)
    for Nnew in (300, 800, 1500, 3000, 6000, 12000):
        if remaining() < 0.6:
            break
        h = _resample(work, Nnew) if Nnew != work.size else work.copy()
        h, c = _refine(h, remaining)
        if c < Cw:
            Cw, work = c, h.copy()
        if c < bestC:
            bestC, best = c, h.copy()

    # NEW: multi-start basin hopping around the best solution
    rng = np.random.default_rng(2025)
    n_tries = 0
    while remaining() > 1.5 and n_tries < 8:
        n_tries += 1
        strength = 0.03 + 0.02 * rng.random()
        hp = _perturb(work, rng, strength=strength)
        # refine at moderate resolution first
        Nmid = min(work.size, 6000)
        hp = _resample(hp, Nmid) if hp.size != Nmid else hp
        hp, cp = _refine(hp, remaining)
        if cp < Cw:
            # promote to full resolution and polish
            if remaining() > 0.8:
                hf = _resample(hp, 12000)
                hf, cf = _refine(hf, remaining)
                if cf < cp:
                    hp, cp = hf, cf
            Cw, work = cp, hp.copy()
            if cp < bestC:
                bestC, best = cp, hp.copy()

    # Final fine-scale polish
    if remaining() > 0.3:
        Nfin = min(12000, max(work.size, 12000))
        h = _resample(work, Nfin)
        h, c = _refine(h, remaining, maxiter=200)
        if c < bestC:
            bestC, best = c, h.copy()

    return np.maximum(np.asarray(best, dtype=float), 0.0)

