import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
from scipy.ndimage import gaussian_filter1d


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad(h):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (S * S)
    grad = np.zeros(N)
    lo = max(0, m - N + 1)
    hi = min(N - 1, m)
    idx = np.arange(lo, hi + 1)
    grad[idx] = 4.0 * N * h[m - idx] / (S * S) - 2.0 * C / S
    return C, grad


def _Ctopk_and_grad(h, eps):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    conv = np.maximum(conv, 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    thr = (1.0 - eps) * mx
    w = (conv >= thr).astype(float)
    sw = w.sum()
    if sw <= 0:
        return np.inf, np.zeros(N)
    w /= sw
    Ctop = 2.0 * N * float(np.sum(w * conv)) / (S * S)
    full = np.convolve(w, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Ctop / S
    return Ctop, grad


def _Cp_and_grad(h, p):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    conv = np.maximum(conv, 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    w = (conv / mx) ** p
    sw = w.sum()
    if sw <= 0:
        return np.inf, np.zeros(N)
    sump = (mx ** p) * sw
    Cp = 2.0 * N * (sump ** (1.0 / p)) / (S * S)
    pref = (sump ** (1.0 / p)) / sump
    dconv = pref * (conv ** (p - 1))
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cp / S
    return Cp, grad


def _Clse_and_grad(h, tau):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    conv = np.maximum(conv, 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    tau = max(tau, 1e-12 * max(mx, 1e-30))
    z = (conv - mx) / tau
    e = np.exp(z)
    se = e.sum()
    lse = mx + tau * np.log(se)
    Cl = 2.0 * N * lse / (S * S)
    dconv = e / se
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cl / S
    return Cl, grad


def _resample(h, Nnew):
    xs = np.linspace(0.0, 1.0, len(h))
    xi = (np.arange(Nnew) + 0.5) / Nnew
    return np.maximum(np.interp(xi, xs, h), 0.0)


def _lbfgs(h0, maxiter=200, p=None, tau=None, eps=None):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    best, bestC = h.copy(), C_of(h)
    if eps is not None:
        fun = lambda x: _Ctopk_and_grad(x, eps)
    elif p is not None:
        fun = lambda x: _Cp_and_grad(x, p)
    elif tau is not None:
        fun = lambda x: _Clse_and_grad(x, tau)
    else:
        fun = _C_and_grad
    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-13})
        xh = np.maximum(res.x, 0.0)
        c = C_of(xh)
        if c < bestC:
            best, bestC = xh, c
    except Exception:
        pass
    return best, bestC


def _polish(h, remaining, maxiter=50):
    c0 = C_of(h)
    if remaining() < 0.3:
        return h, c0
    hp, cp = _lbfgs(h, maxiter=maxiter, p=64)
    if cp < C_of(h):
        h = hp
    if remaining() < 0.25:
        return h, C_of(h)
    ht, ct = _lbfgs(h, maxiter=maxiter, eps=3e-4)
    if ct < C_of(h):
        h = ht
    for frac in (3e-4, 1e-4):
        if remaining() < 0.2:
            break
        conv = np.convolve(h, h)
        mx = conv.max()
        hl, cl = _lbfgs(h, maxiter=maxiter, tau=frac * mx)
        if cl < C_of(h):
            h = hl
    if remaining() > 0.15:
        h, c = _lbfgs(h, maxiter=maxiter, p=None)
    else:
        c = C_of(h)
    return h, c


def _param_shape(c, w, p, N=300):
    x = (np.arange(N) + 0.5) / N - 0.5
    u = (x - c) / w
    base = 1.0 - u * u
    h = np.where(base > 0.0, np.power(np.maximum(base, 0.0), p), 0.0)
    return h


def _poly_shape(a, b, c, d, N=400):
    x = (np.arange(N) + 0.5) / N - 0.5
    u = 2.0 * x
    u2 = u * u
    base = 1.0 - u2
    h = np.zeros(N)
    mask = base > 0.0
    h[mask] = np.power(base[mask], a) * np.exp(
        b * u2[mask] + c * u2[mask] ** 2 + d * u2[mask] ** 3)
    return np.maximum(h, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.88 * budget_seconds

    def remaining():
        return deadline - time.process_time()

    best = None
    bestC = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            best, bestC = s.copy(), C_of(s)

    if best is None:
        N = 200
        x = (np.arange(N) + 0.5) / N
        u = 2.0 * x - 1.0
        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    # ---- Parametric family global search (base) ----
    Np = 300
    try:
        def obj(v):
            c, w, p = v
            h = _param_shape(c, w, p, Np)
            if h.sum() <= 0:
                return 1e6
            return C_of(h)

        bounds = [(-0.05, 0.05), (0.10, 0.25), (0.5, 4.0)]
        res = differential_evolution(obj, bounds, popsize=15, maxiter=60,
                                     seed=0, tol=1e-10, polish=True,
                                     init='latinhypercube')
        c, w, p = res.x
        hparam = _param_shape(c, w, p, Np)
        cparam = C_of(hparam)
        print("param C", cparam, "c", c, "w", w, "p", p)
        if cparam < bestC:
            bestC, best = cparam, hparam.copy()
            print("param improved", bestC)
    except Exception as e:
        print("param search failed", e)

    # ---- NEW: polynomial-exponent family global search ----
    try:
        def objp(v):
            a, b, c, d = v
            h = _poly_shape(a, b, c, d, 400)
            if h.sum() <= 0:
                return 1e6
            return C_of(h)

        bounds_p = [(0.2, 3.0), (-20.0, 20.0), (-20.0, 20.0), (-20.0, 20.0)]
        resp = differential_evolution(objp, bounds_p, popsize=15, maxiter=40,
                                      seed=1, tol=1e-10, polish=True,
                                      init='latinhypercube')
        a, b, c, d = resp.x
        hp = _poly_shape(a, b, c, d, 400)
        cp = C_of(hp)
        print("poly C", cp, "a", a, "b", b, "c", c, "d", d)
        if cp < bestC:
            bestC, best = cp, hp.copy()
            print("poly improved", bestC)
    except Exception as e:
        print("poly search failed", e)

    # ---- Polish with remaining time ----
    if remaining() > 0.5:
        # resample to N=3000 for finer polish
        h3k = _resample(best, 3000)
        hp, cp = _polish(h3k, remaining, maxiter=60)
        if cp < bestC:
            bestC, best = cp, hp.copy()
            print("polish improved", bestC)

    return np.maximum(np.asarray(best, dtype=float), 0.0)

