    bestC = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            best, bestC = s.copy(), C_of(s)

    if best is None:
        N = 200
        x = (np.arange(N) + 0.5) / N
        u = 2.0 * x - 1.0
        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    work = best.copy()
    Cw = bestC

    # Baseline polish preserving start resolution
    work, Cw = _polish(work, remaining, maxiter=70)
    if Cw < bestC:
        bestC, best = Cw, work.copy()

    # Focused coordinate descent with shrinking step (kept from p0167)
    rng = np.random.default_rng(1234567)
    Np = 300
    if work.size != Np:
        work = _resample(work, Np)
        Cw = C_of(work)

    it = 0
    step = 0.15
    while remaining() > 0.5 and step > 1e-5:
        it += 1
        improved = False
        nz = np.where(work > 0)[0]
        if nz.size == 0:
            break
        k = max(1, nz.size // 20)
        idx = rng.choice(nz, size=min(k, nz.size), replace=False)
        scale = step * (work.max() if work.max() > 0 else 1.0)
        cand = work.copy()
        cand[idx] = np.maximum(cand[idx] + rng.standard_normal(idx.size) * scale, 0.0)
        if cand.sum() <= 0:
            continue
        cc = C_of(cand)
        if cc < Cw * (1.0 + 5e-4) and remaining() > 1.0:
            hc, ccp = _polish(cand, remaining, maxiter=40)
            if ccp < Cw:
                work, Cw = hc, ccp
                improved = True
        elif cc < Cw:
            work, Cw = cand, cc
            improved = True

        if improved:
            if Cw < bestC:
                bestC, best = Cw, work.copy()
                print("improved", bestC, "iter", it, "N", work.size)
            step = min(step * 1.3, 0.2)
        else:
            step *= 0.97

    # Key addition: derivative-free coordinate polish on the true-C
    # directly at the working resolution, exploiting the plateau structure.
    # For each coordinate, try a small local line search on true C.
    if remaining() > 0.6:
        h = _resample(best, Np)
        c = C_of(h)
        deltas = [0.05, 0.02, 0.01, 0.005, 0.002, 0.001]
        improved_any = True
        rounds = 0
        while improved_any and remaining() > 0.4 and rounds < 40:
            improved_any = False
            rounds += 1
            order = rng.permutation(Np)
            for i in order:
                if remaining() < 0.3:
                    break
                base_val = h[i]
                bval = base_val
                bC = c
                for d in deltas:
                    for sign in (1.0, -1.0):
                        nv = base_val + sign * d * (h.max() if h.max() > 0 else 1.0)
                        if nv < 0:
                            continue
                        h[i] = nv
                        cc = C_of(h)
                        if cc < bC - 1e-12:
                            bC = cc
                            bval = nv
                h[i] = bval
                if bC < c - 1e-12:
                    c = bC
                    improved_any = True
            if c < bestC:
                bestC, best = c, h.copy()
                print("coord", bestC, "round", rounds, "N", h.size)

    # Final high-res polish
    if remaining() > 0.2:
        Nfin = min(1500, max(best.size, 800))
        h = _resample(best, Nfin)
        h, c = _polish(h, remaining, maxiter=120)
        if c < bestC:
            bestC, best = c, h.copy()

    return np.maximum(np.asarray(best, dtype=float), 0.0)

