    for _ in range(iters):
        hp = h.copy()
        hp[1:-1] = 0.25 * h[:-2] + 0.5 * h[1:-1] + 0.25 * h[2:]
        h = np.maximum(hp, 0.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.85 * budget_seconds

    def remaining():
        return deadline - time.process_time()

    best = None
    bestC = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            best, bestC = s.copy(), C_of(s)

    if best is None:
        N = 200
        x = (np.arange(N) + 0.5) / N
        u = 2.0 * x - 1.0
        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    work = best.copy()
    Cw = bestC

    # Ensure at least moderate resolution
    Np = 300
    if work.size != Np:
        work = _resample(work, Np)
        Cw = C_of(work)

    # Baseline polish
    work, Cw = _polish(work, remaining, maxiter=70)
    if Cw < bestC:
        bestC, best = Cw, work.copy()

    rng = np.random.default_rng(987654321)

    # Main loop: multi-resolution smoothing + polish + random perturbation
    it = 0
    step = 0.10
    while remaining() > 0.5 and step > 1e-5:
        it += 1
        improved = False

        # Strategy A: smooth current work then polish (smoothing helps escape
        # peaky local minima by redistributing mass in flat maximum)
        if remaining() > 1.0:
            hs = _smooth(work, iters=1)
            hs, cs = _polish(hs, remaining, maxiter=40)
            if cs < Cw:
                work, Cw = hs, cs
                improved = True

        # Strategy B: random perturbation on support region
        if not improved and remaining() > 0.5:
            nz = np.where(work > 0)[0]
            if nz.size > 0:
                k = max(1, nz.size // 25)
                idx = rng.choice(nz, size=min(k, nz.size), replace=False)
                scale = step * (work.max() if work.max() > 0 else 1.0)
                cand = work.copy()
                cand[idx] = np.maximum(
                    cand[idx] + rng.standard_normal(idx.size) * scale, 0.0)
                if cand.sum() > 0:
                    cc = C_of(cand)
                    if cc < Cw * (1.0 + 3e-4) and remaining() > 1.0:
                        hc, ccp = _polish(cand, remaining, maxiter=35)
                        if ccp < Cw:
                            work, Cw = hc, ccp
                            improved = True
                    elif cc < Cw:
                        work, Cw = cand, cc
                        improved = True

        if improved:
            if Cw < bestC:
                bestC, best = Cw, work.copy()
                print("improved", bestC, "iter", it, "N", work.size)
            step = min(step * 1.2, 0.15)
        else:
            step *= 0.96

        # Periodic resolution bump with refinement
        if it % 25 == 0 and remaining() > 1.5:
            Nr = min(1200, max(best.size * 2, 600))
            hr = _resample(best, Nr)
            hr, cr = _polish(hr, remaining, maxiter=60)
            if cr < bestC:
                bestC, best = cr, hr.copy()
                work = _resample(best, Np)
                Cw = C_of(work)
                print("rebase", bestC, "N", best.size)

    # Final high-res polish
    if remaining() > 0.3:
        Nfin = min(3000, max(best.size * 2, 1500))
        h = _resample(best, Nfin)
        h, c = _polish(h, remaining, maxiter=120)
        if c < bestC:
            bestC, best = c, h.copy()

    return np.maximum(np.asarray(best, dtype=float), 0.0)

import numpy as np
import time
from scipy.optimize import minimize


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad(h):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (S * S)
    grad = np.zeros(N)
    lo = max(0, m - N + 1)
    hi = min(N - 1, m)
    idx = np.arange(lo, hi + 1)
    grad[idx] = 4.0 * N * h[m - idx] / (S * S) - 2.0 * C / S
    return C, grad


def _Cp_and_grad(h, p):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.maximum(np.convolve(h, h), 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    w = (conv / mx) ** p
    sw = w.sum()
    if sw <= 0:
        return np.inf, np.zeros(N)
    sump = (mx ** p) * sw
    Cp = 2.0 * N * (sump ** (1.0 / p)) / (S * S)
    pref = (sump ** (1.0 / p)) / sump
    dconv = pref * (conv ** (p - 1))
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cp / S
    return Cp, grad


def _Clse_and_grad(h, tau):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.maximum(np.convolve(h, h), 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    tau = max(tau, 1e-12 * max(mx, 1e-30))
    z = (conv - mx) / tau
    e = np.exp(z)
    se = e.sum()
    lse = mx + tau * np.log(se)
    Cl = 2.0 * N * lse / (S * S)
    dconv = e / se
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cl / S
    return Cl, grad


def _resample(h, Nnew):
    xs = np.linspace(0.0, 1.0, len(h))
    xi = (np.arange(Nnew) + 0.5) / Nnew
    return np.maximum(np.interp(xi, xs, h), 0.0)


def _lbfgs(h0, maxiter=200, p=None, tau=None):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    best, bestC = h.copy(), C_of(h)
    if p is not None:
        fun = lambda x: _Cp_and_grad(x, p)
    elif tau is not None:
        fun = lambda x: _Clse_and_grad(x, tau)
    else:
        fun = _C_and_grad
    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-13})
        xh = np.maximum(res.x, 0.0)
        c = C_of(xh)
        if c < bestC:
            best, bestC = xh, c
    except Exception:
        pass
    return best, bestC


def _polish(h, remaining, maxiter=60):
    if remaining() < 0.3:
        return h, C_of(h)
    for p in (16, 64):
        if remaining() < 0.25:
            break
        hp, cp = _lbfgs(h, maxiter=maxiter, p=p)
        if cp < C_of(h):
            h = hp
    for frac in (3e-3, 1e-3, 3e-4, 1e-4):
        if remaining() < 0.2:
            break
        conv = np.convolve(h, h)
        mx = conv.max()
        hl, cl = _lbfgs(h, maxiter=maxiter, tau=frac * mx)
        if cl < C_of(h):
            h = hl
    if remaining() > 0.15:
        h, c = _lbfgs(h, maxiter=maxiter)
    else:
        c = C_of(h)
    return h, c


