    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad(h):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (S * S)
    grad = np.zeros(N)
    lo = max(0, m - N + 1)
    hi = min(N - 1, m)
    idx = np.arange(lo, hi + 1)
    grad[idx] = 4.0 * N * h[m - idx] / (S * S) - 2.0 * C / S
    return C, grad


def _Ctopk_and_grad(h, eps):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    conv = np.maximum(conv, 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    thr = (1.0 - eps) * mx
    w = (conv >= thr).astype(float)
    sw = w.sum()
    if sw <= 0:
        return np.inf, np.zeros(N)
    w /= sw
    Ctop = 2.0 * N * float(np.sum(w * conv)) / (S * S)
    full = np.convolve(w, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Ctop / S
    return Ctop, grad


def _Cp_and_grad(h, p):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    conv = np.maximum(conv, 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    w = (conv / mx) ** p
    sw = w.sum()
    if sw <= 0:
        return np.inf, np.zeros(N)
    sump = (mx ** p) * sw
    Cp = 2.0 * N * (sump ** (1.0 / p)) / (S * S)
    pref = (sump ** (1.0 / p)) / sump
    dconv = pref * (conv ** (p - 1))
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cp / S
    return Cp, grad


def _lbfgs(h0, maxiter=200, p=None, eps=None):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    best, bestC = h.copy(), C_of(h)
    if eps is not None:
        fun = lambda x: _Ctopk_and_grad(x, eps)
    elif p is not None:
        fun = lambda x: _Cp_and_grad(x, p)
    else:
        fun = _C_and_grad
    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-13})
        xh = np.maximum(res.x, 0.0)
        c = C_of(xh)
        if c < bestC:
            best, bestC = xh, c
    except Exception:
        pass
    return best, bestC


def _polish(h, remaining, maxiter=60):
    c0 = C_of(h)
    if remaining() < 0.3:
        return h, c0
    for p in (4, 8, 16, 32, 64, 128, 256):
        if remaining() < 0.25:
            break
        hp, cp = _lbfgs(h, maxiter=maxiter, p=p)
        if cp < C_of(h):
            h = hp
    if remaining() < 0.25:
        return h, C_of(h)
    for eps in (1e-2, 3e-3, 1e-3, 3e-4, 1e-4):
        if remaining() < 0.2:
            break
        ht, ct = _lbfgs(h, maxiter=maxiter, eps=eps)
        if ct < C_of(h):
            h = ht
    if remaining() > 0.15:
        h, c = _lbfgs(h, maxiter=maxiter, p=None)
    else:
        c = C_of(h)
    return h, c


def _mix_to_h(params, N):
    """params: 12 values [w1..w4, c1..c4, s1..s4]."""
    w = np.maximum(params[0:4], 0.0)
    c = params[4:8]
    s = np.maximum(params[8:12], 1e-3)
    x = (np.arange(N) + 0.5) / N - 0.5  # in [-0.5, 0.5]
    h = np.zeros(N)
    for k in range(4):
        h += w[k] * np.exp(-((x - c[k]) / s[k]) ** 2)
    return h


def _mix_C(params, N=200):
    h = _mix_to_h(params, N)
    if h.sum() <= 0:
        return 1e6
    return C_of(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.85 * budget_seconds

    def remaining():
        return deadline - time.process_time()

