        u = 2.0 * x - 1.0
        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    # --- Gaussian mixture DE search ---
    if remaining() > 2.0:
        bounds = ([(0.0, 1.0)] * 4 +
                  [(-0.25, 0.25)] * 4 +
                  [(0.005, 0.2)] * 4)
        try:
            de_budget = max(0.5, min(remaining() - 1.5, 0.5 * budget_seconds))
            # differential_evolution doesn't take wall time; use modest popsize/iters
            res = differential_evolution(
                _mix_C, bounds, maxiter=60, popsize=12, tol=1e-8,
                mutation=(0.5, 1.0), recombination=0.7,
                polish=False, seed=12345, workers=1)
            params = res.x
            # resample to N=1200
            Nnew = 1200
            h_mix = _mix_to_h(params, Nnew)
            if h_mix.sum() > 0:
                c_mix = C_of(h_mix)
                print("DE mixture C at N=1200:", c_mix)
                if remaining() > 0.5:
                    hp, cp = _polish(h_mix, remaining, maxiter=80)
                    if cp < bestC:
                        bestC, best = cp, hp.copy()
                        print("mixture polish improved", bestC)
                    else:
                        print("mixture polish no improvement (best", bestC, ")")
        except Exception as e:
            print("DE failed:", e)

    # --- Continue base multi-resolution polish from best ---
    for Nnew in (600, 1200):
        if remaining() < 1.0:
            break
        xs = np.linspace(0.0, 1.0, len(best))
        xi = (np.arange(Nnew) + 0.5) / Nnew
        up = np.maximum(np.interp(xi, xs, best), 0.0)
        up = up / up.sum() if up.sum() > 0 else up
        c_up = C_of(up)
        if c_up <= bestC * 1.002:
            hu, cu = _polish(up, remaining, maxiter=60)
            if cu < bestC:
