                print("upsampled", Nnew, "improved", bestC)

    if remaining() > 0.5:
        hp, cp = _polish(best.copy(), remaining, maxiter=80)
        if cp < bestC:
            bestC, best = cp, hp.copy()
            print("final polish improved", bestC)

    return np.maximum(np.asarray(best, dtype=float), 0.0)

