        hp, cp = _lbfgs(h, maxiter=maxiter, p=p)
        if cp < C_of(h):
            h = hp
    for frac in (3e-3, 1e-3, 3e-4, 1e-4):
        if remaining() < 0.2:
            break
        conv = np.convolve(h, h)
        mx = conv.max()
        hl, cl = _lbfgs(h, maxiter=maxiter, tau=frac * mx)
        if cl < C_of(h):
            h = hl
    if remaining() > 0.15:
        h, c = _lbfgs(h, maxiter=maxiter)
    else:
        c = C_of(h)
    return h, c


def _sqp_step(h, remaining):
    """Deterministic active-set SQP step on the max of conv(h,h)."""
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return h, C_of(h)
    conv = np.convolve(h, h)
    mx = conv.max()
    if mx <= 0:
        return h, C_of(h)
    # active set of t-indices near the max
    A = np.where(conv >= mx - 1e-4 * mx)[0]
    if A.size == 0:
        A = np.array([int(np.argmax(conv))])
    k = A.size
    # average gradient: g_i = (1/k) sum_{t in A} 2 * h[t-i]  (valid i where 0<=t-i<N)
    g = np.zeros(N)
    H = np.zeros((N, N))
    # Build H as (2/k) * sum over t in A of E_t, where E_t[i,j]=1 if i+j=t.
    # We'll accumulate via outer products of indicator vectors.
    for t in A:
        lo = max(0, t - N + 1)
        hi = min(N - 1, t)
        if hi < lo:
            continue
        idx = np.arange(lo, hi + 1)
        g[idx] += 2.0 * h[t - idx]
        # H contribution: 2 * (indicator outer indicator)
        H[np.ix_(idx, idx)] += 2.0
    g /= k
    H /= k
    # KKT system: [[H, 1],[1^T, 0]] [dh; dlam] = [-g; 0]
    # Add small ridge for numerical stability
    ridge = 1e-9 * (np.trace(H) / max(N, 1) + 1e-30)
    Hr = H + ridge * np.eye(N)
    KKT = np.zeros((N + 1, N + 1))
    KKT[:N, :N] = Hr
    KKT[:N, N] = 1.0
    KKT[N, :N] = 1.0
    rhs = np.zeros(N + 1)
    rhs[:N] = -g
    try:
        sol = np.linalg.solve(KKT, rhs)
    except np.linalg.LinAlgError:
        return h, C_of(h)
    dh = sol[:N]
    if not np.all(np.isfinite(dh)):
        return h, C_of(h)
    # backtracking line search on exact C
    baseC = C_of(h)
    best_h = h
    best_C = baseC
    alpha = 1.0
    for _ in range(25):
        cand = np.maximum(h + alpha * dh, 0.0)
        if cand.sum() <= 0:
            alpha *= 0.5
            continue
        cc = C_of(cand)
        if cc < best_C:
            best_h, best_C = cand, cc
        if cc < baseC:
            break
        alpha *= 0.5
        if remaining() < 0.05:
            break
    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.85 * budget_seconds

    def remaining():
        return deadline - time.process_time()

    best = None
    bestC = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            best, bestC = s.copy(), C_of(s)

    if best is None:
        N = 200
        x = (np.arange(N) + 0.5) / N
        u = 2.0 * x - 1.0
        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    work = best.copy()
    Cw = bestC

    Np = 300
    if work.size != Np:
        work = _resample(work, Np)
        Cw = C_of(work)

    # baseline polish
    work, Cw = _polish(work, remaining, maxiter=70)
    if Cw < bestC:
        bestC, best = Cw, work.copy()

    # Deterministic active-set SQP loop
    it = 0
    while remaining() > 0.4 and it < 300:
        it += 1
        hnew, cnew = _sqp_step(work, remaining)
        if cnew < Cw - 1e-12:
            work, Cw = hnew, cnew
            if Cw < bestC:
                bestC, best = Cw, work.copy()
                print("improved", bestC, "iter", it, "N", work.size)
        else:
            # no progress: re-polish and try again
            if remaining() > 1.0:
                work, Cw = _polish(work, remaining, maxiter=40)
                if Cw < bestC:
                    bestC, best = Cw, work.copy()
                    print("polish", bestC, "iter", it, "N", work.size)
            else:
                break

        # periodically re-polish and re-base at higher resolution
        if it % 25 == 0 and remaining() > 1.5:
            Nr = min(1500, max(best.size, 800))
            hr = _resample(best, Nr)
            hr, cr = _polish(hr, remaining, maxiter=60)
            if cr < bestC:
                bestC, best = cr, hr.copy()
                work = _resample(best, Np)
                Cw = C_of(work)
                print("rebase", bestC, "N", best.size)

    # Final high-res polish
    if remaining() > 0.2:
        Nfin = min(3000, max(best.size, 1500))
        h = _resample(best, Nfin)
        h, c = _polish(h, remaining, maxiter=120)
        if c < bestC:
            bestC, best = c, h.copy()

    return np.maximum(np.asarray(best, dtype=float), 0.0)

import numpy as np
import time
from scipy.optimize import minimize


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad(h):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (S * S)
    grad = np.zeros(N)
    lo = max(0, m - N + 1)
    hi = min(N - 1, m)
    idx = np.arange(lo, hi + 1)
    grad[idx] = 4.0 * N * h[m - idx] / (S * S) - 2.0 * C / S
    return C, grad


def _Clse_and_grad(h, tau):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.maximum(np.convolve(h, h), 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    tau = max(tau, 1e-12 * mx)
    z = (conv - mx) / tau
    e = np.exp(z)
    se = e.sum()
    lse = mx + tau * np.log(se)
    Cl = 2.0 * N * lse / (S * S)
    dconv = e / se
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cl / S
    return Cl, grad


def _resample(h, Nnew):
    xs = np.linspace(0.0, 1.0, len(h))
    xi = (np.arange(Nnew) + 0.5) / Nnew
    return np.maximum(np.interp(xi, xs, h), 0.0)


def _lbfgs(h0, maxiter=200, tau=None):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    best, bestC = h.copy(), C_of(h)
    fun = _C_and_grad if tau is None else (lambda x: _Clse_and_grad(x, tau))
    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-13})
        xh = np.maximum(res.x, 0.0)
        c = C_of(xh)
        if c < bestC:
            best, bestC = xh, c
    except Exception:
        pass
    return best, bestC


def _lse_ladder(h, fracs, maxiter, remaining):
    for frac in fracs:
        if remaining() < 0.5:
            break
        conv = np.convolve(h, h)
        mx = conv.max()
        hl, cl = _lbfgs(h, maxiter=maxiter, tau=frac * mx)
        if cl < C_of(h):
            h = hl
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.85 * budget_seconds

    def remaining():
