        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    work = best.copy()
    Cw = bestC

    # The start is at N=5000; the plateau structure benefits from finer
    # resolution. Refine at the start's N first (cheap), then push N up
    # while polishing the plateau with an LSE ladder.
    Nstart = work.size
    ladder_sizes = [Nstart]
    for n in (8000, 12000, 18000, 24000, 30000):
        if n not in ladder_sizes:
            ladder_sizes.append(n)

    for Nnew in ladder_sizes:
        if remaining() < 0.6:
            break
        h = _resample(work, Nnew) if Nnew != work.size else work.copy()
        h = _lse_ladder(h, (3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5), 80, remaining)
        if remaining() < 0.4:
            break
        h, c = _lbfgs(h, maxiter=150, tau=None)
        if c < Cw:
            Cw, work = c, h.copy()
        if c < bestC:
            bestC, best = c, h.copy()

    # Final push: full resolution with a long cold ladder and exact polish.
    if remaining() > 0.5:
        Nfin = min(30000, max(work.size, 24000))
        h = _resample(work, Nfin)
        h = _lse_ladder(h, (1e-3, 3e-4, 1e-4, 3e-5, 1e-5, 3e-6, 1e-6),
                        100, remaining)
        if remaining() > 0.4:
            h, c = _lbfgs(h, maxiter=300, tau=None)
            if c < bestC:
                bestC, best = c, h.copy()

