from scipy.optimize import minimize


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad(h):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (S * S)
    grad = np.zeros(N)
    lo = max(0, m - N + 1)
    hi = min(N - 1, m)
    idx = np.arange(lo, hi + 1)
    grad[idx] = 4.0 * N * h[m - idx] / (S * S) - 2.0 * C / S
    return C, grad


def _Cp_and_grad(h, p):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.maximum(np.convolve(h, h), 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    w = (conv / mx) ** p
    sw = w.sum()
    if sw <= 0:
        return np.inf, np.zeros(N)
    sump = (mx ** p) * sw
    Cp = 2.0 * N * (sump ** (1.0 / p)) / (S * S)
    pref = (sump ** (1.0 / p)) / sump
    dconv = pref * (conv ** (p - 1))
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cp / S
    return Cp, grad


def _Clse_and_grad(h, tau):
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.maximum(np.convolve(h, h), 0.0)
    mx = conv.max()
    if mx <= 0:
        return np.inf, np.zeros(N)
    tau = max(tau, 1e-12 * max(mx, 1e-30))
    z = (conv - mx) / tau
    e = np.exp(z)
    se = e.sum()
    lse = mx + tau * np.log(se)
    Cl = 2.0 * N * lse / (S * S)
    dconv = e / se
    full = np.convolve(dconv, h[::-1])
    grad_conv = 2.0 * full[N - 1: 2 * N - 1]
    grad = 2.0 * N * grad_conv / (S * S) - 2.0 * Cl / S
    return Cl, grad


def _resample(h, Nnew):
    xs = np.linspace(0.0, 1.0, len(h))
    xi = (np.arange(Nnew) + 0.5) / Nnew
    return np.maximum(np.interp(xi, xs, h), 0.0)


def _lbfgs(h0, maxiter=200, p=None, tau=None):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    best, bestC = h.copy(), C_of(h)
    if p is not None:
        fun = lambda x: _Cp_and_grad(x, p)
    elif tau is not None:
        fun = lambda x: _Clse_and_grad(x, tau)
    else:
        fun = _C_and_grad
    try:
        res = minimize(fun, h, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-13})
        xh = np.maximum(res.x, 0.0)
        c = C_of(xh)
        if c < bestC:
            best, bestC = xh, c
    except Exception:
        pass
    return best, bestC


def _polish(h, remaining, maxiter=60):
    if remaining() < 0.3:
        return h, C_of(h)
    for p in (16, 64):
        if remaining() < 0.25:
            break
        hp, cp = _lbfgs(h, maxiter=maxiter, p=p)
        if cp < C_of(h):
            h = hp
    for frac in (3e-3, 1e-3, 3e-4, 1e-4):
        if remaining() < 0.2:
            break
        conv = np.convolve(h, h)
        mx = conv.max()
        hl, cl = _lbfgs(h, maxiter=maxiter, tau=frac * mx)
        if cl < C_of(h):
            h = hl
    if remaining() > 0.15:
        h, c = _lbfgs(h, maxiter=maxiter)
    else:
        c = C_of(h)
    return h, c


def _active_set_step(h, remaining, rel_tol=1e-4, reg=1e-8, max_rounds=5):
    """Simultaneous linearized active-set step on the true C."""
    h = np.asarray(h, dtype=float).copy()
    N = h.size
    c = C_of(h)
    for _ in range(max_rounds):
        if remaining() < 0.35:
            break
        conv = np.convolve(h, h)
        M = conv.max()
        if M <= 0:
            break
        active = np.where(conv > M * (1.0 - rel_tol))[0]
        if active.size == 0:
            break
        # Build A: rows = gradient of conv_t wrt h, i.e. A[t, i] = 2*h[t-i] for valid i
        A = np.zeros((active.size, N))
        for r, t in enumerate(active):
            lo = max(0, t - N + 1)
            hi = min(N - 1, t)
            idx = np.arange(lo, hi + 1)
            A[r, idx] = 2.0 * h[t - idx]
        b = (M - conv[active])
        # Regularized least squares: (A^T A + reg I) delta = A^T b
        AtA = A.T @ A
        AtA[np.diag_indices_from(AtA)] += reg
        Atb = A.T @ b
        try:
            delta = np.linalg.solve(AtA, Atb)
        except np.linalg.LinAlgError:
            try:
                delta = np.linalg.lstsq(AtA, Atb, rcond=None)[0]
            except Exception:
                break
        if not np.all(np.isfinite(delta)):
            break
        # Rescale so sum(delta)=0 (preserve sum h)
        s = delta.sum()
        if abs(s) > 1e-15:
            delta = delta - s / N
        # Bound: h+delta >= 0
        neg = (h + delta) < 0
        if np.any(neg):
            # shrink delta to keep nonneg
            with np.errstate(divide='ignore', invalid='ignore'):
                ratios = np.where(delta < 0, -h / delta, np.inf)
            max_alpha = min(1.0, float(np.min(ratios)) * 0.999)
            if max_alpha <= 0:
                break
            delta = delta * max_alpha
        # Line search
        alpha = 1.0
        accepted = False
        best_h = None
        best_c = c
        for _ls in range(12):
            cand = h + alpha * delta
            cand = np.maximum(cand, 0.0)
            if cand.sum() <= 0:
                alpha *= 0.5
                continue
            cc = C_of(cand)
            if cc < best_c - 1e-15:
                best_c = cc
                best_h = cand
                accepted = True
                break
            alpha *= 0.5
        if not accepted:
            break
        h = best_h
        c = best_c
    return h, c


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.88 * budget_seconds

    def remaining():
        return deadline - time.process_time()

    best = None
    bestC = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            best, bestC = s.copy(), C_of(s)

    if best is None:
        N = 200
        x = (np.arange(N) + 0.5) / N
        u = 2.0 * x - 1.0
        best = np.maximum(0.0, (1.0 - u * u))
        bestC = C_of(best)

    work = best.copy()
    Cw = bestC

    # Baseline polish preserving start resolution
    work, Cw = _polish(work, remaining, maxiter=70)
    if Cw < bestC:
        bestC, best = Cw, work.copy()

    # Active-set step after initial polish
    if remaining() > 0.6:
        hw, cw = _active_set_step(work, remaining)
        if cw < Cw:
            work, Cw = hw, cw
            if Cw < bestC:
                bestC, best = Cw, work.copy()
                print("activeset1", bestC, "N", work.size)

    # Focused coordinate descent with shrinking step (kept from p0167)
    rng = np.random.default_rng(1234567)
    Np = 300
    if work.size != Np:
        work = _resample(work, Np)
        Cw = C_of(work)

    it = 0
    step = 0.15
    while remaining() > 0.5 and step > 1e-5:
        it += 1
        improved = False
        nz = np.where(work > 0)[0]
        if nz.size == 0:
            break
        k = max(1, nz.size // 20)
        idx = rng.choice(nz, size=min(k, nz.size), replace=False)
        scale = step * (work.max() if work.max() > 0 else 1.0)
        cand = work.copy()
        cand[idx] = np.maximum(cand[idx] + rng.standard_normal(idx.size) * scale, 0.0)
        if cand.sum() <= 0:
            continue
        cc = C_of(cand)
        if cc < Cw * (1.0 + 5e-4) and remaining() > 1.0:
            hc, ccp = _polish(cand, remaining, maxiter=40)
            if ccp < Cw:
                work, Cw = hc, ccp
                improved = True
        elif cc < Cw:
            work, Cw = cand, cc
            improved = True

        if improved:
            if Cw < bestC:
                bestC, best = Cw, work.copy()
                print("improved", bestC, "iter", it, "N", work.size)
            step = min(step * 1.3, 0.2)
        else:
            step *= 0.97

    # Active-set step after coordinate descent
    if remaining() > 0.6:
        hw, cw = _active_set_step(work, remaining)
        if cw < Cw:
            work, Cw = hw, cw
            if Cw < bestC:
                bestC, best = Cw, work.copy()
                print("activeset2", bestC, "N", work.size)

    # Derivative-free coordinate polish on true C
    if remaining() > 0.6:
        h = _resample(best, Np)
        c = C_of(h)
        deltas = [0.05, 0.02, 0.01, 0.005, 0.002, 0.001]
        improved_any = True
        rounds = 0
        while improved_any and remaining() > 0.4 and rounds < 40:
            improved_any = False
            rounds += 1
            order = rng.permutation(Np)
            for i in order:
                if remaining() < 0.3:
                    break
                base_val = h[i]
                bval = base_val
                bC = c
                for d in deltas:
                    for sign in (1.0, -1.0):
                        nv = base_val + sign * d * (h.max() if h.max() > 0 else 1.0)
                        if nv < 0:
                            continue
                        h[i] = nv
                        cc = C_of(h)
                        if cc < bC - 1e-12:
                            bC = cc
                            bval = nv
                h[i] = bval
                if bC < c - 1e-12:
                    c = bC
                    improved_any = True
            if c < bestC:
                bestC, best = c, h.copy()
                print("coord", bestC, "round", rounds, "N", h.size)

    # Final active-set step on best
    if remaining() > 0.5:
        hw, cw = _active_set_step(best, remaining)
        if cw < bestC:
            bestC, best = cw, hw.copy()
            print("activeset3", bestC, "N", best.size)

    # Final high-res polish
    if remaining() > 0.2:
        Nfin = min(1500, max(best.size, 800))
        h = _resample(best, Nfin)
        h, c = _polish(h, remaining, maxiter=120)
        if c < bestC:
            bestC, best = c, h.copy()

    return np.maximum(np.asarray(best, dtype=float), 0.0)

