def _perturb(h, rng, strength=0.05):
    N = len(h)
    x = np.linspace(0, 1, N)
    log_m = np.zeros(N)
    for k in range(1, 5):
        a = rng.standard_normal() * strength
        b = rng.standard_normal() * strength
        log_m += a * np.cos(2 * np.pi * k * x) + b * np.sin(2 * np.pi * k * x)
    return np.maximum(h * np.exp(log_m), 0.0)


